/* ============================================================
   MOTOR DE CÁLCULO — lê tudo dos cadastros
   ============================================================ */
const lookup=(v,t)=>{
  if(!Array.isArray(t))return 0;
  const r=t.find(x=>v>=Number(x.min)&&v<=Number(x.max));
  if(!r)return 0;
  return r.pricePerGT?v*Number(r.pricePerGT):Number(r.price||0);
};
/* Tipos de navio — definem qual coluna da tabela de praticagem se aplica */
const VTYPES={
  bulk:'Graneleiro / Carga Geral',
  container:'Contêiner / Ro-Ro / PCC / Passageiro'
};
/* Acordos de praticagem são do PORTO (cada praticagem tem os seus).
   O armador indica o acordo padrão e, se preciso, um acordo específico por porto. */
const agreementsOf=port=>(port&&Array.isArray(port.agreements)&&port.agreements.length)?port.agreements:['SINDASC','CNTT'];
const agreementOf=(s,port)=>{
  const list=agreementsOf(port);
  const want=((s&&s.portAgreements)||{})[(port||{}).id]||(s&&s.pilotage_agreement)||list[0];
  return list.includes(want)?want:list[0];
};
const agreementMismatch=(s,port)=>{
  const want=((s&&s.portAgreements)||{})[(port||{}).id]||(s&&s.pilotage_agreement);
  return !!want&&!agreementsOf(port).includes(want);
};
const keysOf=port=>agreementsOf(port).flatMap(a=>[a+'_BULK',a+'_CONT']);
/* taxas de agenciamento: valor específico do porto, se houver; senão o padrão do armador */
const feesFor=(s,port)=>{
  const o=(((s||{}).portFees)||{})[(port||{}).id];
  const pick=k=>Number(o&&o[k]!=null&&o[k]!==''?o[k]:(s||{})[k]||0);
  return{agency_fee:pick('agency_fee'),psp_fee:pick('psp_fee'),communication_fee:pick('communication_fee'),car_hire_fee:pick('car_hire_fee')};
};
const typeOf=(vessel,shipowner)=>{
  const t=vessel&&vessel.vesselType;
  if(t==='bulk'||t==='container')return t;
  return (shipowner&&shipowner.cntt_table==='T1')?'container':'bulk';   /* compatibilidade */
};
const tableKey=(shipowner,vessel,port)=>
  agreementOf(shipowner,port)+'_'+(typeOf(vessel,shipowner)==='container'?'CONT':'BULK');
/* Portos cadastrados antes da separação por tipo de navio */
const LEGACY_KEY={SINDASC_BULK:'SINDASC',SINDASC_CONT:'SINDASC',CNTT_BULK:'CNTT_T2',CNTT_CONT:'CNTT_T1'};
const pickTable=(tables,key)=>{
  const t=tables||{};
  return t[key]||t[LEGACY_KEY[key]]||null;
};
const TKEYS=['SINDASC_BULK','SINDASC_CONT','CNTT_BULK','CNTT_CONT'];
const agOfKey=k=>String(k).slice(0,String(k).lastIndexOf('_'));
const tkLabel=k=>agOfKey(k)+' · '+(String(k).endsWith('_CONT')?'Contêiner / Passageiro':'Graneleiro / Carga Geral');

/* ---------- Empresa e armador alimentando FDA, PDA e invoice ---------- */
const CompaniesCtx=React.createContext(SEED_COMPANIES);
/* empresa por id; sem id ou id inexistente → a padrão */
const companyOf=(list,id)=>{
  const l=list||SEED_COMPANIES;
  return l.find(c=>c.id===id)||l.find(c=>c.isDefault)||l[0]||SEED_COMPANY;
};
/* conta do armador só vale se pertencer à empresa emitente */
const ownerBankFor=(so,co)=>(so&&co&&(so.companyId||co.id)===co.id)?so.bankAccountId:'';
/* referência para os geradores de PDF resolverem o logo sem receber a lista */
let COMPANIES_REF=SEED_COMPANIES;
const logoOf=companyId=>{
  const co=companyOf(COMPANIES_REF,companyId);
  if(co.logo)return co.logo;                       /* data URL enviado no cadastro */
  return co.id==='co_seatrade'?'data:image/png;base64,'+LOGO_B64:'';
};
async function embedLogoFor(doc,companyId){
  const src=logoOf(companyId);
  if(!src)return null;
  const [head,b64]=src.split(',');
  try{ return /jpe?g/i.test(head)?await doc.embedJpg(b64bytes(b64)):await doc.embedPng(b64bytes(b64)); }
  catch(e){ return null; }
}
const OwnersCtx=React.createContext([]);
const bankOf=(co,id)=>{
  const list=(co&&co.bankAccounts)||[];
  return list.find(b=>b.id===id)||list.find(b=>b.isDefault)||list[0]||null;
};
const companyAddress=co=>[co.address,[co.city,co.state].filter(Boolean).join(' - '),co.zip?'CEP '+co.zip:''].filter(Boolean).join(' - ');
/* bloco "Dados para remessa" do FDA */
function remitFrom(co,bankId){
  const b=bankOf(co,bankId)||{};
  return{agent:co.legalName||'',agentAddress:companyAddress(co),
    remitTo:b.beneficiary||co.legalName||'',
    bank:[b.bank,b.agency?'Agency '+b.agency:''].filter(Boolean).join(' - '),
    account:b.account||'',swift:[b.iban,b.swift].filter(Boolean).join(' / '),bankAccountId:b.id||''};
}
/* bloco do cliente: razão social + endereço de faturamento + identificação fiscal */
function clientFrom(so){
  if(!so)return{};
  const addr=[so.billingAddress||'',so.taxId||''].filter(Boolean).join('\n');
  return{shipownerId:so.id,to:so.legalName||so.name||'',clientAddress:addr,
    currency:so.invoiceCurrency||'USD'};
}
/* dados bancários no formato do PDA */
function bankRows(co,bankId){
  const b=bankOf(co,bankId);
  if(!b)return[];
  return[['Beneficiary',b.beneficiary||co.legalName],
    ['C.N.P.J.',[co.cnpj,co.zip?'CEP '+co.zip:''].filter(Boolean).join(' - ')],
    ['Bank',b.bank],['Address',b.bankAddress],['City',b.bankCity],['Country',co.country||'Brazil'],
    ['Agency / Account',[b.agency,b.account].filter(Boolean).join(' / ')],
    ['Swift Code',b.swift],['IBAN',b.iban]].filter(r=>r[1]);
}

/* quantidade movimentada em toneladas, lida do campo "Quantidade" da escala (ex: "30.000 MT") */
const cargoTons=v=>{
  const t=String((v||{}).quantity||'').replace(/[^\d.,]/g,'');
  if(!t)return 0;
  const n=t.includes(',')?parseFloat(t.replace(/\./g,'').replace(',','.')):parseFloat(t.replace(/\.(?=\d{3}(\D|$))/g,''));
  return isFinite(n)?n:0;
};

/* Alíquota do canal de acesso conforme o tipo de carga da escala.
   Portos cadastrados antes da tabela por carga continuam usando per_dwt. */
function acRate(ac,cargoType){
  const list=(ac||{}).rates;
  if(!Array.isArray(list)||!list.length)
    return{value:Number((ac||{}).per_dwt||0),name:'taxa única por DWT',found:true};
  const hit=list.find(r=>r.id===cargoType);
  if(hit)return{value:Number(hit.value||0),name:hit.name,found:true};
  return{value:0,name:'tipo de carga não informado',found:false};
}

/* Vigência de tarifa — 'YYYY-MM-DD' comparado como string ISO */
const today=()=>new Date().toISOString().slice(0,10);
function vigStatus(o,ref){
  if(!o)return{state:'none'};
  const f=o.from||'',t=o.to||'';
  if(!f&&!t)return{state:'none'};
  if(f&&ref<f)return{state:'future',from:f,to:t};
  if(t&&ref>t)return{state:'expired',from:f,to:t};
  return{state:'ok',from:f,to:t};
}
const fDateBR=d=>{ if(!d)return'—'; const p=String(d).split('-'); return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:d; };

/* Alertas de tarifa — lidos na cotação, não alteram o cálculo */
function tariffWarnings({port,shipowner,vessel,supState,suppliers,refDate,terminals}){
  const w=[],ref=refDate||today();
  (terminals||[]).forEach(t=>{
    const v=vigStatus(t.wharfage_config,ref);
    if(v.state==='expired')w.push({kind:'bad',text:`O wharfage do ${t.name} venceu em ${fDateBR(v.to)}.`});
    if(v.state==='future')w.push({kind:'warn',text:`A tarifa de wharfage do ${t.name} só entra em vigor em ${fDateBR(v.from)}.`});
  });
  const ag=agreementOf(shipowner,port), key=tableKey(shipowner,vessel,port);
  if(agreementMismatch(shipowner,port))
    w.push({kind:'warn',text:`O acordo de praticagem do armador não existe em ${port.city}. Foi usado ${ag} — confira o cadastro do armador.`});
  const ac0=port.access_channel||{};
  if(ac0.enabled&&ac0.basis==='cargo'&&!(cargoTons(vessel)>0))
    w.push({kind:'bad',text:'O canal de acesso deste porto é cobrado por tonelada movimentada — informe a quantidade em toneladas.'});
  const pv=(port.pilotage_validity||{})[ag];
  const st=vigStatus(pv,ref);
  if(st.state==='none')w.push({kind:'warn',text:`A tabela de praticagem ${ag} não tem vigência informada. Cadastre em Portos › Praticagem.`});
  if(st.state==='expired')w.push({kind:'bad',text:`A tabela de praticagem ${ag} venceu em ${fDateBR(st.to)}. O valor calculado está defasado.`});
  if(st.state==='future')w.push({kind:'warn',text:`A tabela de praticagem ${ag} só entra em vigor em ${fDateBR(st.from)}.`});
  if(!pickTable(port.pilotage_tables,key))w.push({kind:'bad',text:`Não há tabela de manobra cadastrada para ${tkLabel(key)}.`});
  else if(lookup(Number(vessel.grossTonnage),pickTable(port.pilotage_tables,key))<=0)
    w.push({kind:'bad',text:`GT ${fN(vessel.grossTonnage)} está fora das faixas da tabela ${tkLabel(key)}. A praticagem saiu zerada.`});
  if(Number(vessel.berthShifts)>0&&!pickTable(port.shift_tables,key))
    w.push({kind:'bad',text:`Não há tabela de mudança de berço para ${tkLabel(key)}.`});
  const acc=port.access_channel||{};
  if(acc.enabled&&Array.isArray(acc.rates)&&acc.rates.length&&!acRate(acc,vessel.cargoType).found)
    w.push({kind:'bad',text:'Informe o tipo de carga — sem ele a parte variável do Access Channel sai zerada.'});
  [['access_channel','Access Channel'],['watchmen','Watchmen']].forEach(([k,lbl])=>{
    const o=port[k]||{}; if(!o.enabled)return;
    const v=vigStatus(o,ref);
    if(v.state==='expired')w.push({kind:'bad',text:`A tarifa de ${lbl} venceu em ${fDateBR(v.to)}.`});
    if(v.state==='future')w.push({kind:'warn',text:`A tarifa de ${lbl} só entra em vigor em ${fDateBR(v.from)}.`});
    if(String(o.source||'').toUpperCase().indexOf('A CONFIRMAR')===0)
      w.push({kind:'warn',text:`A tarifa de ${lbl} está marcada como "a confirmar" no cadastro.`});
  });
  (suppliers||port.suppliers||[]).forEach(sp=>{
    const stt=(supState||{})[sp.id];
    if(!stt||!stt.enabled)return;
    if(Number(stt.value)!==Number(sp.default_rate))
      w.push({kind:'info',text:`${sp.name}: valor usado ${stt.currency} ${fBRLplain(stt.value)} difere do cadastro (${sp.currency} ${fBRLplain(sp.default_rate)}).`});
  });
  return w;
}
const usd=(v,cur,fx)=>cur==='USD'?Number(v||0):Number(v||0)/fx;

function calcWharfage(term,{loa,portStay,hasContract}){
  /* tarifas por hora: fração de hora conta como hora cheia (SCPar Tab. II "por hora ou fração") */
  const c=term.wharfage_config||{}, h=Math.ceil(Number(portStay)*24-1e-9), L=Number(loa)||0;
  switch(c.model){
    case 'tiered_hourly':{
      const fh=Number(c.first_hours||48),r1=Number(c.first_rate||0),r2=Number(c.after_rate||0);
      if(h<=fh)return{brl:L*r1*h,formula:`${L}m × R$ ${r1} × ${h}h`,label:''};
      return{brl:L*r1*fh+L*r2*(h-fh),formula:`${L}m × [${fh}h × R$ ${r1} + ${h-fh}h × R$ ${r2}]`,label:''};
    }
    case 'contract_dual':{
      if(hasContract){
        const ph=Number(c.contract_period_hours||6),rt=Number(c.contract_rate_per_meter||0),p=Math.ceil(h/ph);
        return{brl:L*rt*p,formula:`${L}m × R$ ${rt} × ${p} períodos de ${ph}h`,label:'Com contrato'};
      }
      return{brl:h*Number(c.no_contract_rate_per_hour||0),formula:`${h}h × R$ ${c.no_contract_rate_per_hour}`,label:'Sem contrato'};
    }
    case 'flat_hourly':return{brl:h*Number(c.rate_per_hour||0),formula:`${h}h × R$ ${c.rate_per_hour}`,label:''};
    case 'flat_daily':return{brl:Number(portStay)*Number(c.rate_per_day||0),formula:`${portStay} dia(s) × R$ ${c.rate_per_day}`,label:''};
    case 'per_loa_daily':return{brl:L*Number(c.rate_per_meter_day||0)*Number(portStay),formula:`${L}m × R$ ${c.rate_per_meter_day} × ${portStay} dia(s)`,label:''};
    default:return{brl:0,formula:'Wharfage não configurado',label:''};
  }
}

function calcExtra(c,{loa,portStay}){
  const v=Number(c.value||0),h=Number(portStay)*24;
  if(c.basis==='per_day')return v*Number(portStay);
  if(c.basis==='per_hour')return v*h;
  if(c.basis==='per_loa')return v*Number(loa);
  if(c.basis==='per_loa_day')return v*Number(loa)*Number(portStay);
  return v;
}

function calculate({port,terminals,shipowner,vessel,supState,suppliers,extras,cityQty}){
  const fx=Number(vessel.exchangeRate)||1;
  const {loa,grossTonnage,deadWeight,portStay,berthShifts}=vessel;
  const city=[];
  const extraAgency=[];   /* custos adicionais lançados na própria cotação */

  /* PRATICAGEM — só entram no PDA/FDA: entrada, saída e mudança de berço.
     A tabela é escolhida pelo acordo do armador × tipo de navio. */
  const key=tableKey(shipowner,vessel,port);
  const pc=port.pilotage_config||{};
  const tarifa=lookup(Number(grossTonnage),pickTable(port.pilotage_tables,key));
  const movs=[];
  if('movEntry' in vessel||'movExit' in vessel){
    if(vessel.movEntry)movs.push('Pilotage In');
    if(vessel.movExit)movs.push('Pilotage Out');
  }else{                                   /* cotações salvas antes da mudança */
    const n=Number(vessel.maneuvers)>0?Number(vessel.maneuvers):2;
    for(let i=0;i<n;i++)movs.push(n<=2?(i===0?'Pilotage In':'Pilotage Out'):`Pilotage — manobra ${i+1}`);
  }
  const agU=agreementOf(shipowner,port);
  const agLbl=agU==='SINDASC'?'Sindasc Table':agU==='CNTT'?'CNTT Table '+(typeOf(vessel,shipowner)==='container'?'1':'2')
    :agU.charAt(0)+agU.slice(1).toLowerCase()+' Table';
  movs.forEach((lbl,i)=>{
    city.push({key:'pil'+i,label:lbl,usd:tarifa/fx,native:tarifa,currency:'BRL',
      acct:pc.acct||ACCT.pilotage,note:`${tkLabel(key)} · tarifa ${fBRLplain(tarifa)}`,
      pdaKey:'pilotage',pdaLabel:pc.pdaLabel||'Pilotage (GRT)',
      comment:(pc.comment||'Maneuver: (Entry / Berthing), (Unberthing/Departure)')+' - '+agLbl});
  });
  const nShift=Number(berthShifts)||0;
  if(nShift>0){
    const tShift=lookup(Number(grossTonnage),pickTable(port.shift_tables,key));
    for(let i=0;i<nShift;i++){
      city.push({key:'shf'+i,label:nShift>1?`Shifting Pilotage ${i+1}`:'Shifting Pilotage',
        usd:tShift/fx,native:tShift,currency:'BRL',
        acct:pc.shiftAcct||ACCT.shift,note:`${tkLabel(key)} · mudança de berço ${fBRLplain(tShift)}`,
        pdaKey:'shifting',pdaLabel:pc.shiftLabel||'Shifting Pilotage (GRT)',
        comment:(pc.shiftComment||'Berth Shifting Maneuvers')+' - '+agLbl});
    }
  }

  (suppliers||port.suppliers||[]).forEach(s=>{
    const st=supState[s.id];
    if(!st||!st.enabled)return;
    const cur=st.currency||s.currency,val=Number(st.value||0);
    city.push({key:'sup'+s.id,label:s.service==='towage'?'Towage':s.service==='mooring'?'Mooring':s.name,
      usd:usd(val,cur,fx),native:val,currency:cur,
      acct:s.acct||(s.service==='towage'?ACCT.towage:s.service==='mooring'?ACCT.mooring:ACCT.customs),
      note:s.name+(s.has_contract?' · contrato direto':''),
      pdaKey:'sup'+s.id,pdaSeq:s.pdaSeq!=null?Number(s.pdaSeq):(s.service==='towage'?20:s.service==='mooring'?80:125),
      pdaLabel:s.pdaLabel||(s.service==='towage'?'Towage (DWT)':s.service==='mooring'?'Mooring / Unmooring':s.name),
      comment:s.comment||s.name});
  });

  const tuf=lookup(Number(deadWeight),TUF_TABLE);
  const ld=port.light_dues||{};
  city.push({key:'tuf',label:'Light Dues (TUF)',usd:tuf,native:tuf,currency:'USD',acct:ACCT.tuf,
    note:'Tabela federal por DWT',pdaKey:'tuf',
    pdaLabel:ld.pdaLabel||'LightDues (DWT)',comment:ld.comment||'Lighthouse Dues Lumpsum'});

  const ac=port.access_channel||{};
  if(ac.enabled){
    const rt=acRate(ac,vessel.cargoType);
    const basis=ac.basis||'dwt';
    const metric=basis==='gt'?Number(grossTonnage):basis==='cargo'?cargoTons(vessel):Number(deadWeight);
    const mLbl=basis==='gt'?'GT':basis==='cargo'?'t carga':'DWT';
    const n=Number(ac.base||0)+metric*rt.value;
    city.push({key:'ac',label:'Access Channel',usd:usd(n,ac.currency,fx),native:n,currency:ac.currency||'BRL',
      acct:ac.acct||ACCT.access_channel,
      note:`${fBRLplain(ac.base)} + (${mLbl} ${fN(metric)} × ${fBRLplain(rt.value)}) · ${rt.name}`,
      pdaKey:'ac',pdaLabel:ac.pdaLabel||'Acces Channel (DWT)',
      comment:ac.comment||'Inframar Tax'});
  }

  /* Taxas da cidade — uma linha por evento quando a cobrança é na entrada e na saída */
  (port.city_costs||[]).forEach(c=>{
    const inc=c.incidence||'fixed', base=Number(c.value||0), cur=c.currency||'BRL';
    const push=(sufixo,val,nota)=>city.push({key:'cc'+c.id+(sufixo||''),
      label:sufixo?`${c.name} — ${sufixo}`:c.name,
      usd:usd(val,cur,fx),native:val,currency:cur,acct:c.acct||ACCT.customs,note:nota||'',
      pdaKey:'cc'+c.id,pdaLabel:c.pdaLabel||c.name,comment:c.comment||'',
      pdaSeq:c.pdaSeq!=null?Number(c.pdaSeq):115});
    const q=(cityQty||{})[c.id];
    const qn=q===undefined||q===null||q===''?null:Math.max(0,Math.round(Number(q)));
    if(inc==='per_day'){ const d=Number(portStay)||0; push('',base*d,`${fBRLplain(base)} × ${d} dia(s)`); }
    else if(inc==='entry_exit'&&qn===null){ push('Entrada',base); push('Saída',base); }
    else{
      const n=qn===null?1:qn;
      if(n===1)push('',base);
      else for(let i=0;i<n;i++)push(`${i+1}ª`,base,`Cobrança ${i+1} de ${n}`);
    }
  });

  /* Custos adicionais informados manualmente nesta cotação (não vêm do cadastro) */
  (extras||[]).forEach((x,i)=>{
    const val=calcExtra(x,{loa,portStay});
    if(!val)return;
    const cur=x.currency||'BRL';
    const line={key:'mx'+(x.id||i),label:x.name||'Custo adicional',
      usd:usd(val,cur,fx),native:val,currency:cur,acct:x.acct||ACCT.customs,
      note:(x.basis&&x.basis!=='fixed'?`${fBRLplain(x.value)} ${BASIS[x.basis]}`:'Lançado na cotação')
        +(x.noGov?' · fora da base do imposto':''),
      manual:true,noGov:!!x.noGov,
      pdaKey:'mx'+(x.id||i),pdaSeq:x.pdaSeq!=null?Number(x.pdaSeq):(x.section==='agency'?140:128),
      pdaLabel:x.pdaLabel||x.name||'Custo adicional',comment:x.comment||''};
    if(x.section==='agency')extraAgency.push(line); else city.push(line);
  });

  const fb=port.fire_brigade||{};
  if(fb.enabled)city.push({key:'fb',label:'Fire Brigade',usd:usd(fb.value,fb.currency,fx),
    native:Number(fb.value||0),currency:fb.currency||'BRL',acct:fb.acct||ACCT.fire_brigade,
    pdaKey:'fb',pdaLabel:fb.pdaLabel||'Fire Brigate Tax',comment:fb.comment||'Municipal Tax (Compulsory)'});

  const wm=port.watchmen||{};
  if(wm.enabled){
    const d=Number(portStay)||0, model=wm.model||'base_extra';
    let n=0,nota='';
    if(model==='per_shift'){
      const r=Number(wm.shift_rate||0), t=Number(wm.shifts_per_day||0);
      n=r*t*d; nota=`${fBRLplain(r)} × ${t} turno(s)/dia × ${d} dia(s)`;
    }else if(model==='per_day'){
      const r=Number(wm.rate_per_day||0);
      n=r*d; nota=`${fBRLplain(r)} × ${d} dia(s)`;
    }else{
      const m=Number(wm.multiplier||1);
      n=(Number(wm.per_extra_day||0)*(d-1)+Number(wm.base||0))*m;
      nota=`(${fBRLplain(wm.per_extra_day)} × ${d-1} + ${fBRLplain(wm.base)})${m!==1?' × '+m:''}`;
    }
    city.push({key:'wm',label:'Watchmen',usd:usd(n,wm.currency,fx),native:n,currency:wm.currency||'BRL',
      acct:wm.acct||ACCT.watchmen,note:nota,
      pdaKey:'wm',pdaLabel:wm.pdaLabel||'Watchmen',comment:wm.comment||'Gangway Watchmen (Compulsory)'});
  }

  const out={};
  terminals.forEach(t=>{
    const ct=(shipowner.terminalContracts||[]).includes(t.id);
    const wf=calcWharfage(t,{loa,portStay,hasContract:ct});
    const cur=(t.wharfage_config||{}).currency||'BRL';
    const wc=t.wharfage_config||{};
    const tl=[{key:'wf',label:`Wharfage · ${t.name}`,usd:usd(wf.brl,cur,fx),native:wf.brl,currency:cur,
      acct:wc.acct||ACCT.wharfage,note:wf.formula,
      pdaKey:'wf',pdaLabel:wc.pdaLabel||'Wharfage (LOA)',
      comment:(wc.comment||'Dockage Charges')+(wf.label?' · '+wf.label:'')}];
    (t.additional_costs||[]).forEach(x=>{
      const n=calcExtra(x,{loa,portStay});
      tl.push({key:'x'+x.id,label:x.name,usd:usd(n,x.currency,fx),native:n,currency:x.currency||'BRL',
        acct:x.acct||ACCT.customs,note:x.basis&&x.basis!=='fixed'?`${x.value} ${BASIS[x.basis]}`:'',
        pdaKey:'x'+x.id,pdaLabel:x.pdaLabel||x.name,comment:x.comment||''});
    });

    const portCosts=[...city,...tl];
    const portUSD=portCosts.reduce((a,l)=>a+l.usd,0);
    const fees=feesFor(shipowner,port);
    const agency=[
      {key:'af',label:'Agency Fee',usd:fees.agency_fee,currency:'USD',acct:ACCT.agency_fee,
       pdaKey:'af',pdaLabel:'Agency Fee',comment:'As Per Agreement'},
      {key:'psp',label:'PSP Fee',usd:fees.psp_fee,currency:'USD',acct:ACCT.psp_fee,
       pdaKey:'psp',pdaLabel:'PSP Fee',comment:'As Per Agreement'},
      {key:'com',label:'Communication',usd:fees.communication_fee,currency:'USD',acct:ACCT.communication,
       pdaKey:'com',pdaLabel:'Communication /Transportation',comment:'As Per Agreement'},
      {key:'car',label:'Car Hire',usd:fees.car_hire_fee,currency:'USD',acct:ACCT.car_hire,
       pdaKey:'car',pdaLabel:'Car Hire',comment:'As Per Agreement'}
    ].filter(l=>l.usd>0).concat(extraAgency);
    const agencyUSD=agency.reduce((a,l)=>a+l.usd,0);
    /* Linhas marcadas como fora da base não compõem os Compulsory Government Charges */
    const semBase=[...portCosts,...agency].filter(l=>l.noGov).reduce((a,l)=>a+l.usd,0);
    const govBase=portUSD+agencyUSD-semBase;
    const gov=[
      {key:'gov',label:`Government Charges · ${(GOV_RATE*100).toFixed(2)}%`,usd:govBase*GOV_RATE,currency:'USD',
       acct:ACCT.gov_charges,pdaKey:'gov',pdaLabel:'Compulsory Government Charges',
       comment:`Brazilian Government Tax (${(GOV_RATE*100).toFixed(2).replace('.',',')}% Over Total Amount)`},
      {key:'bnk',label:'Bank Charges',usd:BANK_USD,currency:'USD',acct:ACCT.bank_charges,
       pdaKey:'bnk',pdaLabel:'Bank Charges',comment:'As Per Agreement'}
    ];
    const govUSD=gov.reduce((a,l)=>a+l.usd,0);
    const total=govBase+govUSD;
    out[t.name]={terminalId:t.id,terminal:t.name,type:t.type,wharfLabel:wf.label,hasContract:ct,
      portCosts,portUSD,agency,agencyUSD,gov,govUSD,totalUSD:total,totalBRL:total*fx,
      byAccount:groupByAccount([...portCosts,...agency,...gov])};
  });
  return out;
}

/* O PDA é o documento do cliente: agrupa por rubrica.
   O FDA continua recebendo as linhas individuais, uma por despesa. */
function groupForPda(lines){
  const out=[],idx={};
  lines.forEach(l=>{
    const k=l.pdaKey||l.key;
    if(idx[k]===undefined){
      idx[k]=out.length;
      out.push({key:k,label:l.pdaLabel||l.label,comment:l.comment||'',usd:0,brl:0,n:0});
    }
    const r=out[idx[k]];
    r.usd+=l.usd||0; r.n+=1;
  });
  return out;
}

