function Auto({label,items,value,onChange,placeholder,getText,renderItem,required}){
const [q,setQ]=useState('');
const [open,setOpen]=useState(false);
const [hi,setHi]=useState(-1);
const box=useRef(null);
const txt=getText||(i=>i.name||'');

useEffect(()=>{ const it=items.find(i=>i.id===value); setQ(it?txt(it):''); },[value,items]);
useEffect(()=>{
  const h=e=>{ if(box.current&&!box.current.contains(e.target))setOpen(false); };
  document.addEventListener('mousedown',h);
  return()=>document.removeEventListener('mousedown',h);
},[]);

const list=items.filter(i=>txt(i).toLowerCase().includes(q.toLowerCase()));
const pick=i=>{ setQ(txt(i)); onChange(i.id); setOpen(false); setHi(-1); };

return(
<div className="field">
<label>{label}{required&&' *'}</label>
<div className="ac" ref={box}>
<input className="inp" value={q} placeholder={placeholder} autoComplete="off"
  onChange={e=>{setQ(e.target.value);setOpen(true);setHi(-1);if(!e.target.value)onChange('');}}
  onFocus={()=>setOpen(true)}
  onKeyDown={e=>{
    if(!open)return;
    if(e.key==='ArrowDown'){e.preventDefault();setHi(p=>Math.min(p+1,list.length-1));}
    else if(e.key==='ArrowUp'){e.preventDefault();setHi(p=>Math.max(p-1,0));}
    else if(e.key==='Enter'&&hi>=0){e.preventDefault();pick(list[hi]);}
    else if(e.key==='Escape')setOpen(false);
  }}/>
{open&&list.length>0&&(
<div className="ac-list">
{list.map((i,n)=>(
<div key={i.id} className={'ac-item'+(n===hi?' on':'')} onMouseEnter={()=>setHi(n)} onClick={()=>pick(i)}>
{renderItem?renderItem(i):<strong>{txt(i)}</strong>}</div>))}
</div>)}
</div>
</div>);
}

