/* Lista com edição individual: cada item abre a própria caixa de edição */
function ItemList({items,onChange,columns,renderDialog,addLabel,empty,newItem,confirmDel}){
const [edit,setEdit]=useState(null);   /* {item, index} ; index -1 = novo */
const save=it=>{
  if(edit.index<0)onChange([...items,it]);
  else onChange(items.map((x,i)=>i===edit.index?it:x));
  setEdit(null);
};
const del=async(i)=>{
  const it=items[i];
  const ok=await ask({title:'Remover item',danger:true,confirmLabel:'Remover',
    message:(confirmDel?confirmDel(it):'Este item')+' será removido.'});
  if(ok)onChange(items.filter((_,j)=>j!==i));
};
return(
<div>
{items.length===0?<p style={{fontSize:'.84rem',color:'var(--fg-muted)',padding:'4px 0 12px'}}>{empty||'Nenhum item.'}</p>:
<div className="tscroll" style={{margin:0,padding:0}}><table style={{minWidth:520}}>
<thead><tr>{columns.map(c=><th key={c.h} className={c.cls||''}>{c.h}</th>)}<th className="ta-c" style={{width:150}}>Ações</th></tr></thead>
<tbody>{items.map((it,i)=>(
<tr key={it.id||i}>{columns.map(c=><td key={c.h} className={c.cls||''}>{c.r(it)}</td>)}
<td><div className="actions" style={{justifyContent:'center'}}>
<button type="button" className="btn btn-line btn-sm" onClick={()=>setEdit({item:it,index:i})}>Editar</button>
<button type="button" className="btn btn-bad btn-sm" onClick={()=>del(i)}>Remover</button></div></td></tr>))}
</tbody></table></div>}
<button type="button" className="btn btn-line btn-sm" style={{marginTop:10}}
  onClick={()=>setEdit({item:newItem(),index:-1})}>{addLabel||'Adicionar'}</button>
{edit&&renderDialog({item:edit.item,isNew:edit.index<0,onSave:save,onClose:()=>setEdit(null)})}
</div>);
}

