function ContractsModule({shipowners,terminals,ports}){
const rows=[];
(shipowners||[]).forEach(s2=>{
  (s2.terminalContracts||[]).forEach(tid=>{
    const t=(terminals||[]).find(x=>x.id===tid);
    const p=t?(ports||[]).find(x=>x.id===t.portId):null;
    rows.push({id:s2.id+'|'+tid,owner:s2.name,terminal:t?t.name:'Terminal removido',
      port:p?p.city:'—',model:t?((MODELS.find(m=>m.value===(t.wharfage_config||{}).model)||{}).label||''):''});
  });
});
return(
<div className="card">
<div className="card-head"><div><h2>Contratos</h2>
<div className="sub">Vínculos armador × terminal, mantidos no cadastro do armador</div></div></div>
<div className="note note-info">
Esta tela é um espelho. Para criar ou desfazer um contrato, abra o armador em <strong>Armadores</strong>
e marque o terminal. O cálculo do wharfage lê daí.
</div>
{rows.length===0?<Empty title="Nenhum contrato registrado"
  text="Marque os terminais contratados no cadastro de cada armador."/>:
<div className="tscroll"><table>
<thead><tr><th>Armador</th><th>Terminal</th><th>Porto</th><th>Modelo de wharfage</th><th>Situação</th></tr></thead>
<tbody>{rows.map(r=>(
<tr key={r.id}>
<td style={{fontWeight:600}}>{r.owner}</td><td>{r.terminal}</td><td>{r.port}</td>
<td style={{fontSize:'.82rem',color:'var(--fg-muted)'}}>{r.model}</td>
<td><span className="chip chip-ok">Com contrato</span></td>
</tr>))}</tbody></table></div>}
</div>);
}

const COA={
  port:{label:"Port",items:[]}, cargo_load:{label:"Cargo-Load",items:[]}, cargo_disch:{label:"Cargo-Discharge",items:[]},
  pre_carriage:{label:"Pre-Carriage",items:[]}, on_carriage:{label:"On-Carriage",items:[]}, securing:{label:"Securing",items:[]},
  equipment:{label:"Equipment",items:[]}, misc:{label:"Miscellaneous",items:[]}, owners:{label:"Owners",items:[]}
};  /* contas carregadas do banco na abertura (plataforma/cadastros.js) */

/* ============================================================
   FDA — Final Disbursement Account
   Plano de contas G2 extraído do template do armador
   ============================================================ */
/* Correspondência entre os custos do PDA e o plano de contas do armador.
   Confirmado contra a prestação da CANELO ARROW 2509. */
const ACCT={
  pilotage:'4122101', shift:'4122102', towage:'4122103', mooring:'4122108',
  tuf:'4122004', access_channel:'4122007', wharfage:'4122001',
  customs:'4122401', immigration:'4122401', sanitary:'4122401',
  boat_clearance:'4122401', fire_brigade:'4122401',
  watchmen:'LOC-01', psp_fee:'LOC-02',
  agency_fee:'4122201', communication:'4122203', car_hire:'4122205',
  gov_charges:'4122204', bank_charges:'4122204'
};
const acctName=(ref,group)=>{
  const gs=group?[group]:GROUP_ORDER;
  for(const g of gs){
    const it=((COA[g]||{}).items||[]).find(x=>x.ref===ref);
    if(it)return it.name;
  }
  return '';
};
const acctGroupOf=ref=>GROUP_ORDER.find(g=>((COA[g]||{}).items||[]).some(x=>x.ref===ref))||'port';
const isLocalAcct=ref=>{
  const g=acctGroupOf(ref);
  const it=((COA[g]||{}).items||[]).find(x=>x.ref===ref);
  return !!(it&&it.local);
};

const GROUP_ORDER=['port','cargo_load','cargo_disch','pre_carriage','on_carriage','securing','equipment','misc','owners'];

function useCaps(){
const [caps,setCaps]=useState({ready:false,db:null,assets:null,downloads:null,user:null});
useEffect(()=>{
  let dead=false;
  (async()=>{
    const g=n=>(window.claude&&window.claude.use)?window.claude.use(n).catch(()=>null):Promise.resolve(null);
    const [db,assets,downloads,user]=await Promise.all([g('db'),g('assets'),g('downloads'),g('user')]);
    if(!dead)setCaps({ready:true,db,assets,downloads,user});
  })();
  return()=>{dead=true;};
},[]);
return caps;
}

const BLANK_FDA=(co)=>({
  companyId:(co||{}).id||'',to:'',clientAddress:'',shipownerId:'',
  agent:'',
  agentAddress:'',
  remitTo:'',bank:'',account:'',swift:'',bankAccountId:'',currency:'USD',
  ...(co?remitFrom(co,''):{}),
  invoiceNo:'',invoiceDate:'',
  vessel:'',voyage:'',port:'',
  arrivedFrom:'',arrivedAt:'',sailedTo:'',sailedAt:'',
  grt:0,dwt:0,loa:0,beam:0,draft:'',
  loadedQty:'',dischargeQty:'',
  roe:5.425,
  advances:[],remarks:'',
  createdAt:new Date().toISOString()
});

function FdaModule({pending,onCreated,onCancelPending,companies,shipowners}){
const R=useRole();
const caps=useCaps();
const [fdas,setFdas]=useState(null);
const [openId,setOpenId]=useState(null);
const [creating,setCreating]=useState(false);
const [aba,setAba]=useState('open');
const [busca,setBusca]=useState('');
const [allV,setAllV]=useState(null);
const busyRef=useRef(false);

/* Cria a prestação a partir de uma cotação aprovada */
useEffect(()=>{
  if(!pending||!caps.ready||!caps.db||busyRef.current)return;
  busyRef.current=true;
  (async()=>{
    try{
      const q=pending.quote, v=q.vessel||{};
      const r=q.terminalResults[pending.terminalName]||{};
      /* cliente e remessa vêm dos cadastros atuais do armador e da empresa */
      const so=(shipowners||[]).find(x=>x.id===(q.shipowner||{}).id)||q.shipowner||null;
      const co=companyOf(companies,v.companyId||(so||{}).companyId||(q.port||{}).companyId);
      const ref=await caps.db.collection('fdas').add({
        ...BLANK_FDA(co),
        ...remitFrom(co,ownerBankFor(so,co)),
        companyId:co.id,
        ...clientFrom(so),
        to:(so&&(so.legalName||so.name))||'',
        vessel:v.name||'', voyage:v.voy||'', beam:Number(v.beam)||0,
        loadedQty:v.operation==='load'||v.operation==='both'?(v.quantity||''):'',
        dischargeQty:v.operation==='discharge'||v.operation==='both'?(v.quantity||''):'',
        port:(q.port&&(q.port.city+(q.port.state?'/'+q.port.state:'')))||'',
        roe:Number(v.exchangeRate)||1,
        loa:Number(v.loa)||0, grt:Number(v.grossTonnage)||0, dwt:Number(v.deadWeight)||0,
        createdAt:new Date().toISOString(),
        pdaId:q.id, pdaTerminal:pending.terminalName
      });
      const rows=r.byAccount||[];
      let n=1;
      for(const a of rows){
        const roe=Number(v.exchangeRate)||1;
        const estUsd=Number(a.usd.toFixed(2));
        const estBrl=Number((a.usd*roe).toFixed(2));
        /* Cada custo previsto vira uma linha de despesa, nunca agrupado */
        const itens=(a.items&&a.items.length?a.items:[{label:a.name,usd:a.usd,currency:'USD'}]);
        const linhas=itens.map(it=>({
          id:uid(),date:'',description:it.label,notes:'',
          brl:Number(((it.currency==='BRL'?Number(it.native||0):Number(it.usd||0)*roe)).toFixed(2)),
          usd:Number(Number(it.usd||0).toFixed(2)),
          fromPda:true
        }));
        await caps.db.collection('vouchers').add({
          fdaId:ref.id, number:n++, group:a.group,
          accountRef:a.local?'':a.ref, accountName:a.name,
          source:'pda', status:'pending',
          estimatedUsd:estUsd, estimatedBrl:estBrl,
          estimatedFrom:(a.from||[]).join(' + '),
          estimatedItems:linhas.map(l=>({description:l.description,brl:l.brl,usd:l.usd})),
          expenses:linhas
        });
      }
      onCreated&&onCreated(q.id,ref.id);
      setOpenId(ref.id);
      toast(`Prestação criada com ${rows.length} voucher(s) a partir da cotação`,'ok');
    }catch(err){
      toast('Falha ao gerar a prestação: '+(err.message||err),'bad');
      onCancelPending&&onCancelPending();
    }
    busyRef.current=false;
  })();
},[pending,caps.ready,caps.db]);

useEffect(()=>{
  if(!caps.ready||!caps.db)return;
  const un=caps.db.collection('fdas').onSnapshot(
    s=>setFdas(s.docs.map(d=>({id:d.id,...d.data()}))),
    ()=>setFdas([]));
  return un;
},[caps.ready,caps.db]);
/* vouchers de todas as prestações — alimentam o andamento na lista */
useEffect(()=>{
  if(!caps.ready||!caps.db)return;
  const un=caps.db.collection('vouchers').onSnapshot(
    s=>setAllV(s.docs.map(d=>({id:d.id,...d.data()}))),
    ()=>setAllV([]));
  return un;
},[caps.ready,caps.db]);

if(!caps.ready)return <div className="card"><Empty title="Carregando" text="Conectando ao armazenamento da prestação de contas."/></div>;

if(!caps.db)return(
<div className="card">
<div className="note note-warn">
<strong>Armazenamento indisponível nesta visualização.</strong> O módulo FDA guarda as prestações
e os comprovantes no servidor do artefato, o que exige estar com a sessão iniciada na claude.ai
e ter permissão de edição sobre esta página. O módulo PDA continua funcionando normalmente.
</div></div>);

if(fdas===null)return <div className="card"><Empty title="Carregando prestações"/></div>;

if(openId){
  const f=fdas.find(x=>x.id===openId);
  if(!f){setOpenId(null);return null;}
  return <FdaDetail fda={f} caps={caps} onBack={()=>setOpenId(null)}/>;
}

const create=async d=>{
  const ref=await caps.db.collection('fdas').add(d);
  setCreating(false); setOpenId(ref.id);
  toast('Prestação criada','ok');
};

const duplicate=async f=>{
  const ok=await ask({title:'Duplicar prestação',confirmLabel:'Duplicar',
    message:`Os vouchers e as despesas de ${f.vessel||'esta FDA'} serão copiados. Os comprovantes anexados não são copiados — cada despesa da nova prestação começa sem documento.`});
  if(!ok)return;
  try{
    const snap=await caps.db.collection('vouchers').where('fdaId','==',f.id).get();
    const src={...f}; delete src.id;
    const ref=await caps.db.collection('fdas').add({...src,
      vessel:f.vessel,voyage:'',invoiceNo:'',invoiceDate:'',
      status:'open',closedAt:null,closing:null,history:[],exports:{},advances:[],
      createdAt:new Date().toISOString(),copiedFrom:f.id});
    for(const d of snap.docs){
      const v=d.data();
      await caps.db.collection('vouchers').add({
        fdaId:ref.id,number:v.number,group:v.group,
        accountRef:v.accountRef||'',accountName:v.accountName,
        source:v.source||'manual',status:'pending',
        estimatedUsd:v.estimatedUsd,estimatedBrl:v.estimatedBrl,estimatedFrom:v.estimatedFrom,
        expenses:(v.expenses||[]).map(e=>({id:uid(),date:e.date||'',description:e.description||'',
          notes:e.notes||'',brl:Number(e.brl||0),usd:e.usd===''||e.usd==null?'':Number(e.usd),fromPda:e.fromPda}))
      });
    }
    toast(`Prestação duplicada com ${snap.docs.length} voucher(s), sem anexos`,'ok');
    setOpenId(ref.id);
  }catch(err){ toast('Falha ao duplicar: '+(err.message||err),'bad'); }
};

return(
<div className="card">
<div className="card-head"><div><h2>Prestações de contas</h2>
<div className="sub">Final Disbursement Account por escala</div></div>
{R.can('fda_editar')&&<button className="btn btn-primary btn-sm" onClick={()=>setCreating(true)}>Nova FDA</button>}</div>

{(()=>{
const normF=t=>String(t||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
const vOf=id=>(allV||[]).filter(v=>v.fdaId===id);
const abertas=fdas.filter(f=>!isClosed(f)), fechadas=fdas.filter(isClosed);
const base=(aba==='closed'?fechadas:abertas).filter(f=>!busca.trim()||normF(busca).split(/\s+/).every(t=>normF([f.vessel,f.voyage,f.invoiceNo,f.to].join(' ')).includes(t)));
const lista=base.slice().sort((x,y)=>String(aba==='closed'?y.closedAt||'':y.createdAt||'').localeCompare(String(aba==='closed'?x.closedAt||'':x.createdAt||'')));
return(<>
<div className="subnav" style={{marginBottom:14}}>
<button className={aba==='open'?'active':''} onClick={()=>setAba('open')}>Em elaboração · {abertas.length}</button>
<button className={aba==='closed'?'active':''} onClick={()=>setAba('closed')}>Finalizadas · {fechadas.length}</button>
</div>
{fdas.length>0&&<div className="hist-tools">
<input className="inp" value={busca} onChange={e=>setBusca(e.target.value)} placeholder="Filtrar por navio, viagem, invoice ou armador" aria-label="Filtrar FDAs"/>
{busca&&<button className="btn btn-line btn-sm" onClick={()=>setBusca('')}>Limpar</button>}
<span style={{fontSize:'.8rem',color:'var(--fg-muted)',marginLeft:'auto'}}>{lista.length} de {aba==='closed'?fechadas.length:abertas.length}</span>
</div>}
{lista.length===0
 ?(aba==='closed'
   ?<Empty title="Nenhuma prestação finalizada" text="Quando todas as condições forem atendidas, finalize a prestação na aba Fechamento da FDA."/>
   :<Empty title="Nenhuma prestação em elaboração" text="Crie uma FDA ou gere uma a partir de um PDA aprovado."/>)
 :aba==='open'
 ?<div className="tscroll"><table>
<thead><tr><th>Navio</th><th>Viagem</th><th>Porto</th><th>Origem</th><th>Andamento</th><th className="ta-r">Despesas</th><th className="ta-r">Criada em</th><th className="ta-c">Ações</th></tr></thead>
<tbody>{lista.map(f=>{
const vs=vOf(f.id), ck=allV?fdaChecklist(f,vs):null;
const it=k=>ck&&ck.items.find(i=>i.k===k);
return(
<tr key={f.id} className={ck&&ck.ready?'row-ready':''}>
<td style={{fontWeight:600}}>{f.vessel||'—'}{ck&&ck.ready&&<div style={{marginTop:4}}><span className="chip chip-info">Pronta para finalizar</span></div>}</td>
<td className="num">{f.voyage||'—'}</td>
<td>{f.port||'—'}</td>
<td>{f.pdaId?<span className="chip chip-info">PDA #{String(f.pdaId).slice(-6)}{f.pdaTerminal?' · '+f.pdaTerminal:''}</span>
  :<span className="chip chip-mute">Avulsa</span>}</td>
<td>{ck?<div className="prog">
<span><b>{vs.length-ck.pend}/{vs.length}</b> vouchers validados</span>
<span><b>{ck.nDocs}/{ck.nExps}</b> comprovantes</span>
<span>{it('pdf').ok?<b style={{color:'var(--ok)'}}>PDF gerado</b>:'PDF pendente'}{it('invoice').ok?'':' · sem invoice'}</span>
</div>:<span style={{fontSize:'.76rem',color:'var(--fg-muted)'}}>…</span>}</td>
<td className="ta-r num">{ck?fUSD(ck.tot.usd):'—'}</td>
<td className="ta-r num" style={{fontSize:'.8rem'}}>{f.createdAt?new Date(f.createdAt).toLocaleDateString('pt-BR'):'—'}</td>
<td><div className="actions" style={{justifyContent:'center'}}>
<button className="btn btn-line btn-sm" onClick={()=>setOpenId(f.id)}>Abrir</button>
<button className="btn btn-line btn-sm" onClick={()=>duplicate(f)}>Duplicar</button>
</div></td></tr>);})}</tbody></table></div>
 :<div className="tscroll"><table>
<thead><tr><th>Navio</th><th>Viagem</th><th>Porto</th><th>Invoice</th><th>Finalizada</th><th className="ta-r">Despesas</th><th className="ta-r">Saldo</th><th className="ta-c">Ações</th></tr></thead>
<tbody>{lista.map(f=>{
const c=f.closing||{};
const zero=Math.abs(c.saldoBrl||0)<0.005;
return(
<tr key={f.id} className="row-closed">
<td style={{fontWeight:600}}>{f.vessel||'—'}<div style={{marginTop:4}}><span className="chip chip-ok">Finalizada</span></div></td>
<td className="num">{f.voyage||'—'}</td>
<td>{f.port||'—'}</td>
<td className="num">{f.invoiceNo||'—'}</td>
<td style={{fontSize:'.8rem'}}><span className="num">{fDT(f.closedAt)}</span>{c.byName&&<div style={{color:'var(--fg-muted)'}}>{c.byName}</div>}</td>
<td className="ta-r num">{fUSD(c.totalUsd)}</td>
<td className="ta-r"><span className="num" style={{fontWeight:700}}>{fUSD(Math.abs(c.saldoUsd||0))}</span>
<div style={{fontSize:'.72rem',color:zero?'var(--ok)':c.saldoUsd>0?'var(--warn)':'var(--bad)'}}>{zero?'Conciliado':c.saldoUsd>0?'A receber':'A devolver'}</div></td>
<td><div className="actions" style={{justifyContent:'center'}}>
<button className="btn btn-line btn-sm" onClick={()=>setOpenId(f.id)}>Abrir</button>
<button className="btn btn-line btn-sm" onClick={()=>duplicate(f)}>Duplicar</button>
</div></td></tr>);})}</tbody></table></div>}
</>);})()}

{creating&&<FdaHeaderDialog fda={null} onSave={create} onClose={()=>setCreating(false)}/>}
</div>);
}

/* ---------- Detalhe de uma FDA ---------- */
function FdaDetail({fda,caps,onBack}){
const R=useRole();
const [tab,setTab]=useState('vouchers');
const [vouchers,setVouchers]=useState(null);
const [editHdr,setEditHdr]=useState(false);
const [openVoucher,setOpenVoucher]=useState(null);
const [newVoucher,setNewVoucher]=useState(false);

useEffect(()=>{
  const un=caps.db.collection('vouchers').where('fdaId','==',fda.id).onSnapshot(
    s=>setVouchers(s.docs.map(d=>({id:d.id,...d.data()}))),
    ()=>setVouchers([]));
  return un;
},[fda.id]);

const list=(vouchers||[]).slice().sort((a,b)=>Number(a.number||0)-Number(b.number||0));
const totals=fdaTotals(list,fda.roe);
const temEstimado=list.some(v=>v.estimatedUsd!==undefined&&v.estimatedUsd!==null);
const estTotal=list.reduce((a,v)=>a+Number(v.estimatedUsd||0),0);
const isVal=v=>v.status==='validated';
const nVal=list.filter(isVal).length;
const pendentes=list.filter(v=>!isVal(v));
const tudoValidado=list.length>0&&pendentes.length===0;
const furoNum=list.some((v,i)=>Number(v.number)!==i+1);
const locked=isClosed(fda);
const travada=()=>{ toast('Prestação finalizada — reabra para alterar','bad'); };
const varCell=(v,t)=>{
  const e=Number(v.estimatedUsd||0);
  if(!e||!t.usd)return <span style={{color:'var(--fg-muted)'}}>—</span>;
  const d=t.usd-e, pct=d/e*100;
  const cor=Math.abs(pct)<2?'var(--fg-muted)':(d>0?'var(--bad)':'var(--ok)');
  return <span style={{color:cor,fontWeight:600}}>{(d>0?'+':'')+pct.toFixed(1)}%</span>;
};

const saveHdr=async d=>{ if(locked)return travada(); await caps.db.doc('fdas/'+fda.id).update(d); setEditHdr(false); toast('Cabeçalho atualizado','ok'); };
const addVoucher=async d=>{
  if(locked)return travada();
  const ref=await caps.db.collection('vouchers').add({...d,fdaId:fda.id,expenses:[],
    source:'manual',status:'validated',validatedAt:new Date().toISOString()});
  setNewVoucher(false); setOpenVoucher(ref.id); toast('Voucher criado','ok');
};

const setVoucherStatus=async(v,st)=>{
  if(!R.can('fda_validar'))return toast('Seu perfil não valida vouchers','bad');
  if(locked)return travada();
  await caps.db.doc('vouchers/'+v.id).update({status:st,
    validatedAt:st==='validated'?new Date().toISOString():null,validatedBy:st==='validated'?(R.me.id||'local'):null});
  toast(st==='validated'?`Voucher ${v.number} validado`:`Voucher ${v.number} reaberto`,'ok');
};

const removeVoucher=async v=>{
  if(locked)return travada();
  const ok=await ask({title:'Remover voucher',danger:true,confirmLabel:'Remover',
    message:`O voucher ${v.number} — ${v.accountName} — será excluído da prestação. Use isto quando a despesa prevista não ocorreu.`});
  if(!ok)return;
  for(const e of (v.expenses||[])){ if(e.assetId&&caps.assets){try{await caps.assets.delete(e.assetId);}catch(err){}} }
  await caps.db.doc('vouchers/'+v.id).delete();
  toast('Voucher removido');
};

/* Numeração contígua — os números são a referência das covers */
const renumber=async()=>{
  if(locked)return travada();
  const ok=await ask({title:'Renumerar vouchers',confirmLabel:'Renumerar',
    message:'Os vouchers serão renumerados em sequência a partir de 1, na ordem atual. Faça isso antes de enviar a prestação ao armador.'});
  if(!ok)return;
  let n=1;
  for(const v of list){
    if(Number(v.number)!==n)await caps.db.doc('vouchers/'+v.id).update({number:n});
    n++;
  }
  toast('Vouchers renumerados','ok');
};

if(openVoucher){
  const v=(vouchers||[]).find(x=>x.id===openVoucher);
  if(!v){setOpenVoucher(null);return null;}
  return <VoucherDetail voucher={v} fda={fda} caps={caps} onBack={()=>setOpenVoucher(null)}/>;
}

return(
<div>
<div className="card">
<div className="card-head">
<div>
<button className="btn btn-line btn-sm" style={{marginBottom:10}} onClick={onBack}>← Prestações</button>
<h2>{fda.vessel||'Navio sem nome'} · {fda.voyage||'—'}</h2>
<div className="sub">{fda.port||'Porto não informado'} · ROE {fda.roe} · Invoice {fda.invoiceNo||'—'}</div>
</div>
{!locked&&<button className="btn btn-line btn-sm" onClick={()=>setEditHdr(true)}>Editar cabeçalho</button>}
</div>
{locked&&<div className="closed-banner">
<strong>Prestação finalizada</strong>
<span>em {fDT(fda.closedAt)}{(fda.closing||{}).byName?' por '+fda.closing.byName:''} · edição travada</span>
<button className="btn btn-line btn-sm" style={{marginLeft:'auto'}} onClick={()=>setTab('close')}>Ver fechamento</button>
</div>}

<div className="subnav">
<button className={tab==='vouchers'?'active':''} onClick={()=>setTab('vouchers')}>Vouchers · {list.length}</button>
<button className={tab==='covers'?'active':''} onClick={()=>setTab('covers')}>Covers</button>
<button className={tab==='main'?'active':''} onClick={()=>setTab('main')}>Main Cover</button>
<button className={tab==='conc'?'active':''} onClick={()=>setTab('conc')}>Conciliação</button>
<button className={tab==='close'?'active':''} onClick={()=>setTab('close')}>Fechamento{locked?' ✓':''}</button>
</div>

{tab==='vouchers'&&<>
<div className="note note-info">
Cada voucher agrupa as despesas de uma conta do plano do armador. A soma do voucher alimenta
a linha correspondente na cover e, dali, a Main Cover — você lança uma vez só.
</div>
{list.length>0&&(
<div className={'valbar '+(tudoValidado?'done':'')}>
<div className="valbar-head">
<strong>{tudoValidado?'Prestação validada':`${nVal} de ${list.length} vouchers validados`}</strong>
<span>{tudoValidado
  ?'Todos os vouchers foram conferidos contra os documentos. A FDA pode ser emitida.'
  :'A FDA só pode ser emitida depois que cada voucher for conferido contra o documento.'}</span>
</div>
<div className="valbar-track"><div className="valbar-fill"
  style={{width:(list.length?Math.round(nVal/list.length*100):0)+'%'}}/></div>
{pendentes.length>0&&
<div className="valbar-list">Pendentes: {pendentes.map(v=>v.number).join(', ')}</div>}
</div>)}
{furoNum&&!locked&&
<div className="note note-warn">
A numeração dos vouchers está fora de sequência. Como é ela que as covers referenciam,
corrija antes de enviar.
<button className="btn btn-line btn-sm" style={{marginLeft:12}} onClick={renumber}>Renumerar</button>
</div>}
{!locked&&<div style={{marginBottom:14}}>
<button className="btn btn-primary btn-sm" onClick={()=>setNewVoucher(true)}>Novo voucher</button>
</div>}
{vouchers===null?<Empty title="Carregando vouchers"/>:
 list.length===0?<Empty title="Nenhum voucher lançado" text="Crie o primeiro voucher escolhendo a conta do plano do armador."/>:
<div className="tscroll"><table>
<thead><tr><th className="ta-c">Nº</th><th>Conta</th><th>Grupo</th><th>Situação</th>
<th className="ta-c">Desp.</th><th className="ta-c">Comprov.</th>
{temEstimado&&<th className="ta-r">Previsto USD</th>}
<th className="ta-r">BRL</th><th className="ta-r">USD</th>{temEstimado&&<th className="ta-r">Variação</th>}
<th className="ta-c">Ações</th></tr></thead>
<tbody>{list.map(v=>{
const t=voucherTotal(v,fda.roe);
const docs=(v.expenses||[]).filter(e=>e.assetId).length;
const n=(v.expenses||[]).length;
return(<tr key={v.id}>
<td className="ta-c num" style={{fontWeight:700}}>{v.number}</td>
<td><strong>{v.accountName}</strong>{v.accountRef&&<div className="num" style={{fontSize:'.74rem',color:'var(--fg-muted)'}}>{v.accountRef}</div>}</td>
<td style={{fontSize:'.82rem'}}>{(COA[v.group]||{}).label}</td>
<td>{isVal(v)?<span className="chip chip-ok">Validado</span>
  :<span className="chip chip-warn">A validar</span>}
{v.source==='pda'&&<div style={{marginTop:3}}><span className="chip chip-mute">do PDA</span></div>}</td>
<td className="ta-c num">{n}</td>
<td className="ta-c">{n===0?<span className="chip chip-mute">—</span>
  :docs===n?<span className="chip chip-ok">{docs}/{n}</span>
  :<span className="chip chip-warn">{docs}/{n}</span>}</td>
{temEstimado&&<td className="ta-r num" style={{color:'var(--fg-muted)'}}>{v.estimatedUsd?fUSD(v.estimatedUsd):'—'}</td>}
<td className="ta-r num">{fBRL(t.brl)}</td>
<td className="ta-r num" style={{fontWeight:600}}>{fUSD(t.usd)}</td>
{temEstimado&&<td className="ta-r num">{varCell(v,t)}</td>}
<td><div className="actions" style={{justifyContent:'center'}}>
<button className="btn btn-line btn-sm" onClick={()=>setOpenVoucher(v.id)}>Abrir</button>
{!locked&&R.can('fda_validar')&&(isVal(v)
 ?<button className="btn btn-line btn-sm" onClick={()=>setVoucherStatus(v,'pending')}>Reabrir</button>
 :<button className="btn btn-go btn-sm" onClick={()=>setVoucherStatus(v,'validated')}>Validar</button>)}
{!locked&&<button className="btn btn-bad btn-sm" onClick={()=>removeVoucher(v)}>Remover</button>}
</div></td></tr>);})}
<tr><td colSpan="6" style={{fontWeight:700,textTransform:'uppercase',fontSize:'.74rem',letterSpacing:'.06em',color:'var(--fg-muted)'}}>Total dos vouchers</td>
{temEstimado&&<td className="ta-r num" style={{fontWeight:700,color:'var(--fg-muted)'}}>{fUSD(estTotal)}</td>}
<td className="ta-r num" style={{fontWeight:700}}>{fBRL(totals.brl)}</td>
<td className="ta-r num" style={{fontWeight:700}}>{fUSD(totals.usd)}</td>
{temEstimado&&<td className="ta-r num" style={{fontWeight:700}}>
  {estTotal>0&&totals.usd>0?((totals.usd-estTotal)/estTotal*100).toFixed(1)+'%':'—'}</td>}
<td></td></tr>
</tbody></table></div>}
</>}

{tab==='covers'&&<CoversView vouchers={list} fda={fda}/>}
{tab==='main'&&<MainCover vouchers={list} fda={fda} caps={caps} tudoValidado={tudoValidado} pendentes={pendentes}/>}
{tab==='conc'&&<ConciliacaoView vouchers={list} fda={fda} caps={caps}/>}
{tab==='close'&&<FechamentoView vouchers={list} fda={fda} caps={caps} onGo={k=>k==='hdr'?(!locked&&setEditHdr(true)):setTab(k)}/>}
</div>

{editHdr&&<FdaHeaderDialog fda={fda} onSave={saveHdr} onClose={()=>setEditHdr(false)}/>}
{newVoucher&&<VoucherDialog existing={list} onSave={addVoucher} onClose={()=>setNewVoucher(false)}/>}
</div>);
}

function voucherTotal(v,roe){
const brl=(v.expenses||[]).reduce((a,e)=>a+Number(e.brl||0),0);
const usd=(v.expenses||[]).reduce((a,e)=>a+(e.usd!==undefined&&e.usd!==null&&e.usd!==''?Number(e.usd):Number(e.brl||0)/Number(roe||1)),0);
return{brl,usd};
}
/* Impressão digital do conteúdo que vai no PDF — muda se qualquer valor, documento ou dado de cobrança mudar */
const fdaFingerprint=(fda,vouchers)=>{
  const src=JSON.stringify([Number(fda.roe||0),fda.invoiceNo||'',fda.invoiceDate||'',fda.to||'',fda.remitTo||'',
    fda.bank||'',fda.account||'',fda.swift||'',(fda.advances||[]).map(a=>[Number(a.brl||0),Number(a.roe||0)]),
    (vouchers||[]).slice().sort((a,b)=>Number(a.number||0)-Number(b.number||0)).map(v=>[v.id,v.number,v.accountRef||'',v.accountName||'',
      (v.expenses||[]).map(e=>[e.id,Number(e.brl||0),e.usd===''||e.usd==null?'':Number(e.usd),e.assetId||'',e.description||'',e.date||'',e.notes||''])])]);
  let h=5381; for(let i=0;i<src.length;i++)h=((h<<5)+h+src.charCodeAt(i))|0;
  return (h>>>0).toString(36);
};
const isClosed=f=>!!f&&f.status==='closed';
const fDT=iso=>iso?new Date(iso).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';
/* Condições para finalizar uma prestação de contas */
function fdaChecklist(fda,vouchers){
  const list=vouchers||[];
  const pend=list.filter(v=>v.status!=='validated');
  const exps=list.flatMap(v=>(v.expenses||[]).filter(e=>Number(e.brl||0)||Number(e.usd||0)));
  const semDoc=exps.filter(e=>!e.assetId);
  const nDocs=exps.length-semDoc.length;
  const fp=fdaFingerprint(fda,list);
  const need=nDocs>0?'docs':'plain';
  const exp=(fda.exports||{})[need];
  const expOk=!!(exp&&exp.fp===fp);
  const remOk=!!(fda.remitTo&&fda.bank&&fda.account);
  const tot=fdaTotals(list,fda.roe);
  const advBrl=(fda.advances||[]).reduce((a,x)=>a+Number(x.brl||0),0);
  const advUsd=(fda.advances||[]).reduce((a,x)=>a+Number(x.brl||0)/Number(x.roe||fda.roe||1),0);
  const items=[
    {k:'vouchers',ok:list.length>0&&pend.length===0,block:true,t:'Todos os vouchers validados',go:'vouchers',
     d:list.length===0?'Nenhum voucher lançado':pend.length?`${pend.length} de ${list.length} a validar — nº ${pend.map(v=>v.number).join(', ')}`:`${list.length} voucher(s) conferido(s)`},
    {k:'docs',ok:exps.length>0&&semDoc.length===0,block:true,t:'Comprovante anexado em todas as despesas',go:'vouchers',
     d:exps.length===0?'Nenhuma despesa com valor lançada':semDoc.length?`${semDoc.length} de ${exps.length} despesa(s) sem documento`:`${nDocs} comprovante(s) anexado(s)`},
    {k:'invoice',ok:!!(fda.invoiceNo&&fda.invoiceDate),block:true,t:'Invoice com número e data',go:'hdr',
     d:fda.invoiceNo?(fda.invoiceDate?`Invoice ${fda.invoiceNo} · ${fda.invoiceDate}`:`Invoice ${fda.invoiceNo} sem data`):'Informe em Editar cabeçalho › Fatura e remessa'},
    {k:'pdf',ok:expOk,block:true,t:need==='docs'?'FDA + comprovantes gerada na versão atual':'FDA em PDF gerada na versão atual',go:'main',
     d:expOk?`Gerada em ${fDT(exp.at)}${exp.byName?' por '+exp.byName:''}`:exp?'Houve alteração depois da última geração — gere de novo na Main Cover':'Ainda não gerada — use o botão na Main Cover'},
    {k:'remit',ok:remOk,block:false,t:'Dados de remessa preenchidos',go:'hdr',
     d:remOk?'Favorecido, banco e conta informados':'Recomendado — sem eles o armador não tem para onde pagar'}
  ];
  return{items,ready:items.filter(i=>i.block).every(i=>i.ok),fp,tot,advBrl,advUsd,
    saldoBrl:tot.brl-advBrl,saldoUsd:tot.usd-advUsd,nDocs,nExps:exps.length,pend:pend.length,need};
}
function fdaTotals(vs,roe){
return vs.reduce((a,v)=>{const t=voucherTotal(v,roe);return{brl:a.brl+t.brl,usd:a.usd+t.usd};},{brl:0,usd:0});
}

/* ---------- Covers ---------- */
function CoversView({vouchers,fda}){
const byGroup={};
GROUP_ORDER.forEach(g=>{byGroup[g]={};});
vouchers.forEach(v=>{
  if(!byGroup[v.group])byGroup[v.group]={};
  const k=v.accountRef+'|'+v.accountName;
  const t=voucherTotal(v,fda.roe);
  if(!byGroup[v.group][k])byGroup[v.group][k]={ref:v.accountRef,name:v.accountName,brl:0,usd:0,nums:[]};
  byGroup[v.group][k].brl+=t.brl;
  byGroup[v.group][k].usd+=t.usd;
  byGroup[v.group][k].nums.push(v.number);
});
const active=GROUP_ORDER.filter(g=>Object.keys(byGroup[g]||{}).length>0);

if(active.length===0)return <Empty title="Nenhuma cover com movimento" text="As covers são montadas a partir dos vouchers lançados."/>;

return(
<div>
<div className="note note-info">
As covers são calculadas a partir dos vouchers — a coluna <strong>Voucher</strong> é a correlação
que o armador usa para auditar cada linha contra o comprovante.
</div>
{active.map(g=>{
const rows=Object.values(byGroup[g]);
const tb=rows.reduce((a,r)=>a+r.brl,0),tu=rows.reduce((a,r)=>a+r.usd,0);
return(
<div className="panel" key={g}>
<div className="panel-head"><h3>{COA[g].label}</h3></div>
<div className="tscroll" style={{margin:0,padding:0}}><table style={{minWidth:520}}>
<thead><tr><th>GB Ref</th><th>Conta</th><th className="ta-c">Voucher</th>
<th className="ta-r">Local Currency</th><th className="ta-r">USD</th></tr></thead>
<tbody>{rows.map((r,i)=>(
<tr key={i}>
<td className="num" style={{fontSize:'.8rem',color:'var(--fg-muted)'}}>{r.ref||'—'}</td>
<td>{r.name}</td>
<td className="ta-c num">{r.nums.join(', ')}</td>
<td className="ta-r num">{fBRL(r.brl)}</td>
<td className="ta-r num">{fUSD(r.usd)}</td>
</tr>))}
<tr><td colSpan="3" style={{fontWeight:700,fontSize:'.76rem',textTransform:'uppercase',letterSpacing:'.06em'}}>Total {COA[g].label}</td>
<td className="ta-r num" style={{fontWeight:700}}>{fBRL(tb)}</td>
<td className="ta-r num" style={{fontWeight:700}}>{fUSD(tu)}</td></tr>
</tbody></table></div>
</div>);})}
</div>);
}

/* ---------- Main Cover ---------- */
function MainCover({vouchers,fda,caps,tudoValidado,pendentes}){
const R=useRole();
const [busy,setBusy]=useState(false);
const rows=GROUP_ORDER.map(g=>{
  const vs=vouchers.filter(v=>v.group===g);
  const brl=vs.reduce((a,v)=>a+voucherTotal(v,fda.roe).brl,0);
  const usd=vs.reduce((a,v)=>a+voucherTotal(v,fda.roe).usd,0);
  return{group:g,label:COA[g].label,brl,usd};
});
const subBrl=rows.reduce((a,r)=>a+r.brl,0),subUsd=rows.reduce((a,r)=>a+r.usd,0);
const advBrl=(fda.advances||[]).reduce((a,x)=>a+Number(x.brl||0),0);
const advUsd=(fda.advances||[]).reduce((a,x)=>a+Number(x.brl||0)/Number(x.roe||fda.roe||1),0);
const dueBrl=subBrl-advBrl, dueUsd=subUsd-advUsd;

const exportFda=async withDocs=>{
  setBusy(true);
  try{
    const ok=await buildFdaPdf({fda,vouchers,rows,subBrl,subUsd,advBrl,advUsd,dueBrl,dueUsd,caps,withDocs});
    /* registra a geração para o fechamento — só vale para o conteúdo exato que foi gerado */
    if(ok&&caps.db&&!isClosed(fda)){
      await caps.db.doc('fdas/'+fda.id).update({exports:{...(fda.exports||{}),
        [withDocs?'docs':'plain']:{at:new Date().toISOString(),fp:fdaFingerprint(fda,vouchers),by:R.me.id||'local',byName:R.me.name||''}}});
    }
  }
  catch(e){ toast('Falha ao gerar o PDF: '+(e.message||e),'bad'); }
  setBusy(false);
};
const nDocs=vouchers.reduce((a,v)=>a+(v.expenses||[]).filter(e=>e.assetId).length,0);

return(
<div>
<div className="tscroll"><table style={{minWidth:520}}>
<thead><tr><th>Expense type</th><th className="ta-r">Local Currency</th>
<th className="ta-c">Exch. rate</th><th className="ta-r">USD</th></tr></thead>
<tbody>
{rows.map(r=>(
<tr key={r.group} style={r.brl===0?{opacity:.45}:undefined}>
<td>{r.label}</td>
<td className="ta-r num">{fBRL(r.brl)}</td>
<td className="ta-c num" style={{fontSize:'.8rem'}}>{fda.roe}</td>
<td className="ta-r num">{fUSD(r.usd)}</td>
</tr>))}
<tr style={{borderTop:'2px solid var(--border-strong)'}}>
<td style={{fontWeight:700}}>Sub Total</td>
<td className="ta-r num" style={{fontWeight:700}}>{fBRL(subBrl)}</td><td></td>
<td className="ta-r num" style={{fontWeight:700}}>{fUSD(subUsd)}</td></tr>
</tbody></table></div>
{(fda.advances||[]).length>0&&<div className="note note-info" style={{marginTop:14}}>
Adiantamentos e saldo devedor/credor estão na aba <strong>Conciliação</strong>.
No PDF, a Main Cover continua trazendo os adiantamentos e o Total Due.
</div>}

{tudoValidado
 ?<div className="note note-info" style={{marginTop:18}}>
   O PDF sai com a Main Cover, uma cover por grupo e, em seguida, cada voucher na ordem do número.
   </div>
 :<div className="note note-warn" style={{marginTop:18}}>
   <strong>A prestação ainda não pode ser emitida.</strong> {(pendentes||[]).length} voucher(s)
   aguardam validação{(pendentes||[]).length?' — nº '+pendentes.map(v=>v.number).join(', '):''}.
   Confira cada um contra o documento e valide na aba Vouchers.
   </div>}
<div style={{display:'flex',gap:10,flexWrap:'wrap'}}>
<button className="btn btn-primary btn-sm" disabled={busy||!caps.downloads||!tudoValidado||!R.can('fda_emitir')}
  onClick={()=>exportFda(false)}>{busy?'Gerando...':'Gerar FDA em PDF'}</button>
<button className="btn btn-line btn-sm" disabled={busy||!caps.downloads||!tudoValidado||nDocs===0||!R.can('fda_emitir')}
  onClick={()=>exportFda(true)}>FDA + comprovantes{nDocs?` (${nDocs})`:''}</button>
{!caps.downloads&&<span style={{fontSize:'.8rem',color:'var(--fg-muted)',alignSelf:'center'}}>
  Download indisponível nesta visualização.</span>}
</div>
</div>);
}

/* ---------- Conciliação: débitos (despesas) x créditos (adiantamentos) ---------- */
const advUsdOf=(a,fda)=>Number(a.brl||0)/Number(a.roe||fda.roe||1);

function AdvanceDialog({item,isNew,fda,onSave,onClose}){
const [f,setF]=useState(()=>({...item}));
const set=(k,v)=>setF(p=>({...p,[k]:v}));
const save=()=>{
  if(!(Number(f.brl)>0))return toast('Informe o valor recebido','bad');
  if(!(Number(f.roe)>0))return toast('Informe a ROE do recebimento','bad');
  onSave({...f,brl:Number(f.brl),roe:Number(f.roe)});
};
const usd=Number(f.brl||0)/Number(f.roe||1);
return(
<ItemDialog title={isNew?'Novo adiantamento':'Editar adiantamento'} sub={f.label||''} onSave={save} onClose={onClose}>
<div className="grid-s">
<div className="field"><label>Identificação</label>
<input value={f.label||''} placeholder="Ex: Adto 01" onChange={e=>set('label',e.target.value)}/></div>
<div className="field"><label>Data do crédito</label>
<input type="date" value={f.date||''} onChange={e=>set('date',e.target.value)}/></div>
<div className="field"><label>Valor recebido R$</label>
<input type="number" step="0.01" value={f.brl||''} onChange={e=>set('brl',e.target.value)}/></div>
<div className="field"><label>ROE do recebimento</label>
<input type="number" step="0.0001" value={f.roe||''} onChange={e=>set('roe',e.target.value)}/></div>
</div>
<div className="field"><label>Observação</label>
<input value={f.note||''} placeholder="Ex: TED, ref. armador" onChange={e=>set('note',e.target.value)}/></div>
<p style={{fontSize:'.8rem',color:'var(--fg-muted)'}}>Equivale a <strong className="num">{fUSD(usd)}</strong>
{Number(f.roe)&&Number(f.roe)!==Number(fda.roe)?<> · pela ROE da FDA ({fda.roe}) seria <span className="num">{fUSD(Number(f.brl||0)/Number(fda.roe||1))}</span></>:null}</p>
</ItemDialog>);
}

function ConciliacaoView({vouchers,fda,caps}){
const R=useRole();
const [cur,setCur]=useState(fda.currency==='BRL'?'BRL':'USD');
const adv=(fda.advances||[]).map((a,i)=>a.id?a:{...a,id:'adv'+i});
const fmt=cur==='BRL'?fBRL:fUSD;
const deb=vouchers.map(v=>{const t=voucherTotal(v,fda.roe);
  return{k:'v'+v.id,date:'',hist:'Voucher '+v.number+' · '+(v.accountName||''),roe:fda.roe,d:{BRL:t.brl,USD:t.usd},c:{BRL:0,USD:0},val:v.status==='validated'};});
const cre=adv.slice().sort((a,b)=>String(a.date||'9').localeCompare(String(b.date||'9'))).map(a=>(
  {k:a.id,date:a.date,hist:'Adiantamento recebido'+(a.label?' · '+a.label:'')+(a.note?' — '+a.note:''),roe:a.roe||fda.roe,
   d:{BRL:0,USD:0},c:{BRL:Number(a.brl||0),USD:advUsdOf(a,fda)},val:true}));
const tot=(arr,side,c)=>arr.reduce((x,r)=>x+r[side][c],0);
const D={BRL:tot(deb,'d','BRL'),USD:tot(deb,'d','USD')}, C={BRL:tot(cre,'c','BRL'),USD:tot(cre,'c','USD')};
const S={BRL:D.BRL-C.BRL,USD:D.USD-C.USD};
const zero=Math.abs(S[cur])<0.005;
const sit=zero?{cls:'ok',t:'Conciliado',s:'Despesas e adiantamentos se compensam'}
  :S[cur]>0?{cls:'warn',t:'A receber do armador',s:'Despesas maiores que os adiantamentos'}
  :{cls:'bad',t:'A devolver ao armador',s:'Adiantamentos maiores que as despesas'};
const advBrl=C.BRL, varUsd=C.USD-advBrl/Number(fda.roe||1);
const temVar=adv.some(a=>Number(a.roe||fda.roe)!==Number(fda.roe))&&Math.abs(varUsd)>=0.005;
const pend=vouchers.filter(v=>v.status!=='validated').length;

const saveAdv=async next=>{
  if(isClosed(fda))return toast('Prestação finalizada — reabra para alterar','bad');
  if(!R.can('fda_editar'))return toast('Seu perfil não altera adiantamentos','bad');
  await caps.db.doc('fdas/'+fda.id).update({advances:next.map(({id,...x})=>({id:id||uid(),...x}))});
  toast('Adiantamentos atualizados','ok');
};

let run=0;
const rows=[...deb,...cre].map(r=>{run+=r.d[cur]-r.c[cur];return{...r,bal:run};});

return(
<div>
<div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:12,flexWrap:'wrap',marginBottom:14}}>
<div className="note note-info" style={{margin:0,flex:'1 1 320px'}}>
Débito = despesas da prestação (vouchers). Crédito = adiantamentos recebidos do armador.
O saldo mostra quanto falta receber ou quanto deve ser devolvido.
</div>
<div className="seg">{['BRL','USD'].map(c=>(
<button key={c} type="button" className={'btn btn-sm '+(cur===c?'btn-primary':'btn-line')} style={{marginLeft:6}} onClick={()=>setCur(c)}>{c==='BRL'?'R$':'US$'}</button>))}</div>
</div>

<div className="rc-kpis">
<div className="rc-kpi"><span>Débitos · despesas</span><strong>{fmt(D[cur])}</strong><small>{vouchers.length} voucher(s){pend?' · '+pend+' a validar':''}</small></div>
<div className="rc-kpi"><span>Créditos · adiantamentos</span><strong>{fmt(C[cur])}</strong><small>{adv.length} lançamento(s)</small></div>
<div className={'rc-kpi '+sit.cls}><span>Saldo (débito − crédito)</span><strong>{fmt(Math.abs(S[cur]))}</strong><small>{cur==='BRL'?fUSD(Math.abs(S.USD)):fBRL(Math.abs(S.BRL))}</small></div>
<div className={'rc-kpi '+sit.cls}><span>Situação</span><strong>{sit.t}</strong><small>{sit.s}</small></div>
</div>

{temVar&&<div className="note note-warn">
Os adiantamentos foram convertidos pela ROE de cada recebimento. Pela ROE da FDA ({fda.roe}) o crédito seria
{' '}<strong className="num">{fUSD(advBrl/Number(fda.roe||1))}</strong> — diferença cambial de
{' '}<strong className="num">{(varUsd>0?'+':'')+fUSD(varUsd)}</strong> a favor {varUsd>0?'do armador':'da agência'}.
</div>}
{pend>0&&<div className="note note-warn">{pend} voucher(s) ainda não validado(s): o débito pode mudar até a validação.</div>}

<div className="panel">
<div className="panel-head"><h3>Extrato da escala · {cur==='BRL'?'R$':'US$'}</h3></div>
{rows.length===0?<p style={{fontSize:'.84rem',color:'var(--fg-muted)'}}>Sem lançamentos.</p>:
<div className="tscroll" style={{margin:0,padding:0}}><table style={{minWidth:640}}>
<thead><tr><th>Data</th><th>Histórico</th><th className="ta-c">ROE</th><th className="ta-r">Débito</th><th className="ta-r">Crédito</th><th className="ta-r">Saldo</th></tr></thead>
<tbody>{rows.map(r=>(
<tr key={r.k}>
<td className="num" style={{fontSize:'.8rem',whiteSpace:'nowrap'}}>{fDateBR(r.date)}</td>
<td>{r.hist}{!r.val&&<span className="chip chip-warn" style={{marginLeft:6}}>a validar</span>}</td>
<td className="ta-c num" style={{fontSize:'.8rem',color:'var(--fg-muted)'}}>{r.roe}</td>
<td className="ta-r num">{r.d[cur]?fmt(r.d[cur]):''}</td>
<td className="ta-r num" style={{color:'var(--ok)'}}>{r.c[cur]?fmt(r.c[cur]):''}</td>
<td className="ta-r num" style={{fontWeight:600}}>{fmt(r.bal)}</td></tr>))}
<tr style={{borderTop:'2px solid var(--border-strong)'}}>
<td colSpan="3" style={{fontWeight:700}}>Totais</td>
<td className="ta-r num" style={{fontWeight:700}}>{fmt(D[cur])}</td>
<td className="ta-r num" style={{fontWeight:700,color:'var(--ok)'}}>{fmt(C[cur])}</td>
<td className="ta-r num" style={{fontWeight:800}}>{fmt(S[cur])}</td></tr>
</tbody></table></div>}
</div>

<div className="panel">
<div className="panel-head"><h3>Adiantamentos recebidos</h3></div>
<fieldset className="lockset" disabled={isClosed(fda)}>
<ItemList items={adv} onChange={saveAdv} addLabel="Lançar adiantamento" empty="Nenhum adiantamento lançado."
  newItem={()=>({id:uid(),label:'',date:'',brl:0,roe:fda.roe,note:''})}
  confirmDel={a=>'O adiantamento '+(a.label||fBRL(a.brl))}
  columns={[
    {h:'Data',r:a=><span className="num" style={{fontSize:'.8rem'}}>{fDateBR(a.date)}</span>},
    {h:'Identificação',r:a=><>{a.label||'—'}{a.note&&<div style={{fontSize:'.74rem',color:'var(--fg-muted)'}}>{a.note}</div>}</>},
    {h:'Valor R$',cls:'ta-r num',r:a=>fBRL(a.brl)},
    {h:'ROE',cls:'ta-c num',r:a=>a.roe||fda.roe},
    {h:'USD',cls:'ta-r num',r:a=>fUSD(advUsdOf(a,fda))}]}
  renderDialog={p=><AdvanceDialog {...p} fda={fda}/>}/>
</fieldset>
</div>
</div>);
}

/* ---------- Fechamento da prestação ---------- */
function FechamentoView({fda,vouchers,caps,onGo}){
const R=useRole();
const ck=fdaChecklist(fda,vouchers);
const closed=isClosed(fda);
const c=fda.closing||{};
const [note,setNote]=useState('');
const [reopen,setReopen]=useState(false);
const [motivo,setMotivo]=useState('');
const quem=()=>({by:R.me.id||'local',byName:R.me.name||''});

const finalizar=async()=>{
  if(!R.can('fda_finalizar'))return toast('Seu perfil não finaliza prestações','bad');
  if(!ck.ready)return toast('Ainda há condições pendentes','bad');
  const ok=await ask({title:'Finalizar prestação',confirmLabel:'Finalizar',
    message:`A FDA de ${fda.vessel||'navio'}${fda.voyage?' · '+fda.voyage:''} será travada para edição. Despesas ${fUSD(ck.tot.usd)} · saldo ${fUSD(ck.saldoUsd)}.`});
  if(!ok)return;
  const at=new Date().toISOString(), w=quem();
  const closing={at,...w,fp:ck.fp,vouchers:vouchers.length,docs:ck.nDocs,
    totalBrl:+ck.tot.brl.toFixed(2),totalUsd:+ck.tot.usd.toFixed(2),
    advBrl:+ck.advBrl.toFixed(2),advUsd:+ck.advUsd.toFixed(2),
    saldoBrl:+ck.saldoBrl.toFixed(2),saldoUsd:+ck.saldoUsd.toFixed(2),note:note.trim()};
  await caps.db.doc('fdas/'+fda.id).update({status:'closed',closedAt:at,closing,
    history:[...(fda.history||[]),{at,...w,action:'closed',note:closing.note,totalUsd:closing.totalUsd,saldoUsd:closing.saldoUsd}]});
  setNote('');
  toast('Prestação finalizada','ok');
};
const confirmarReabertura=async()=>{
  if(!R.can('fda_reabrir'))return toast('Só o administrador reabre uma prestação finalizada','bad');
  if(motivo.trim().length<5)return toast('Explique o motivo da reabertura','bad');
  const at=new Date().toISOString(), w=quem();
  await caps.db.doc('fdas/'+fda.id).update({status:'open',closedAt:null,closing:null,
    history:[...(fda.history||[]),{at,...w,action:'reopened',note:motivo.trim()}]});
  setReopen(false); setMotivo('');
  toast('Prestação reaberta','ok');
};

const icon=it=>it.ok?<i className="ck-i ok">✓</i>:it.block?<i className="ck-i bad">✕</i>:<i className="ck-i warn">!</i>;
const goLbl={vouchers:'Ir para vouchers',main:'Ir para Main Cover',hdr:'Editar cabeçalho'};
const hist=(fda.history||[]).slice().reverse();
const alterada=closed&&c.fp&&c.fp!==ck.fp;

return(
<div>
{closed?<>
<div className="closed-banner" style={{marginBottom:14}}>
<strong>Finalizada em {fDT(fda.closedAt)}</strong>
<span>{c.byName?'por '+c.byName+' · ':''}{c.vouchers||0} voucher(s) · {c.docs||0} comprovante(s)</span>
{R.can('fda_reabrir')&&<button className="btn btn-line btn-sm" style={{marginLeft:'auto'}} onClick={()=>setReopen(true)}>Reabrir prestação</button>}
</div>
{alterada&&<div className="note note-bad"><strong>Atenção:</strong> o conteúdo atual difere do que foi finalizado. Algo foi alterado fora do fluxo — confira antes de reenviar ao armador.</div>}
<div className="rc-kpis">
<div className="rc-kpi"><span>Despesas</span><strong>{fUSD(c.totalUsd)}</strong><small>{fBRL(c.totalBrl)}</small></div>
<div className="rc-kpi"><span>Adiantamentos</span><strong>{fUSD(c.advUsd)}</strong><small>{fBRL(c.advBrl)}</small></div>
<div className={'rc-kpi '+(Math.abs(c.saldoBrl||0)<0.005?'ok':(c.saldoUsd>0?'warn':'bad'))}>
<span>Saldo no fechamento</span><strong>{fUSD(Math.abs(c.saldoUsd||0))}</strong>
<small>{Math.abs(c.saldoBrl||0)<0.005?'Conciliado':c.saldoUsd>0?'A receber do armador':'A devolver ao armador'}</small></div>
</div>
{c.note&&<div className="note note-info"><strong>Observação:</strong> {c.note}</div>}
</>:<>
<div className="note note-info">
Finalizar trava a prestação para edição e registra quem fechou, quando e com quais valores.
Só é possível com todas as condições obrigatórias atendidas.
</div>
<div className="panel">
<div className="panel-head"><h3>Condições para finalizar</h3>
<span className={'chip '+(ck.ready?'chip-ok':'chip-warn')}>{ck.ready?'Pronta para finalizar':ck.items.filter(i=>i.block&&!i.ok).length+' pendente(s)'}</span></div>
{ck.items.map(it=>(
<div className="ck" key={it.k}>
{icon(it)}
<div className="ck-b"><strong>{it.t}{!it.block&&<span className="chip chip-mute" style={{marginLeft:8}}>recomendado</span>}</strong><span>{it.d}</span></div>
{!it.ok&&it.go&&<button className="btn btn-line btn-sm" onClick={()=>onGo(it.go)}>{goLbl[it.go]}</button>}
</div>))}
</div>
<div className="rc-kpis">
<div className="rc-kpi"><span>Despesas</span><strong>{fUSD(ck.tot.usd)}</strong><small>{fBRL(ck.tot.brl)}</small></div>
<div className="rc-kpi"><span>Adiantamentos</span><strong>{fUSD(ck.advUsd)}</strong><small>{fBRL(ck.advBrl)}</small></div>
<div className={'rc-kpi '+(Math.abs(ck.saldoBrl)<0.005?'ok':(ck.saldoUsd>0?'warn':'bad'))}>
<span>Saldo</span><strong>{fUSD(Math.abs(ck.saldoUsd))}</strong>
<small>{Math.abs(ck.saldoBrl)<0.005?'Conciliado':ck.saldoUsd>0?'A receber do armador':'A devolver ao armador'}</small></div>
</div>
<div className="field"><label>Observação do fechamento</label>
<textarea rows="2" value={note} onChange={e=>setNote(e.target.value)}
  placeholder="Ex: Enviada ao armador por e-mail em 13/10. Saldo a receber via TED."/></div>
<button className="btn btn-go" disabled={!ck.ready||!R.can('fda_finalizar')} onClick={finalizar}>Finalizar prestação</button>
{!R.can('fda_finalizar')&&<span style={{marginLeft:12,fontSize:'.8rem',color:'var(--fg-muted)'}}>Seu perfil não finaliza prestações.</span>}
</>}

{hist.length>0&&<div className="panel" style={{marginTop:18}}>
<div className="panel-head"><h3>Histórico do fechamento</h3></div>
{hist.map((h,i)=>(
<div className="hist-ev" key={i}>
<span className={'chip '+(h.action==='closed'?'chip-ok':'chip-warn')}>{h.action==='closed'?'Finalizada':'Reaberta'}</span>
{' '}<span className="num">{fDT(h.at)}</span>{h.byName?' · '+h.byName:''}
{h.action==='closed'&&h.totalUsd!=null?<span style={{color:'var(--fg-muted)'}}> · {fUSD(h.totalUsd)} · saldo {fUSD(h.saldoUsd)}</span>:null}
{h.note&&<div style={{color:'var(--fg-muted)',marginTop:3}}>{h.note}</div>}
</div>))}
</div>}

{reopen&&<Dialog size="sm" title="Reabrir prestação" sub={(fda.vessel||'')+(fda.voyage?' · '+fda.voyage:'')} onClose={()=>setReopen(false)}>
<div className="note note-warn">A prestação volta para edição. Os vouchers continuam validados até alguém alterá-los.
Depois de corrigir, gere a FDA de novo e finalize outra vez.</div>
<div className="field"><label>Motivo da reabertura *</label>
<textarea rows="3" value={motivo} onChange={e=>setMotivo(e.target.value)} placeholder="Ex: Armador contestou o valor do wharfage — nota de crédito do terminal."/></div>
<div className="form-actions">
<button type="button" className="btn btn-line btn-sm" onClick={()=>setReopen(false)}>Cancelar</button>
<button type="button" className="btn btn-bad btn-sm" onClick={confirmarReabertura}>Reabrir</button></div>
</Dialog>}
</div>);
}

/* ---------- Voucher: despesas e comprovantes ---------- */
function VoucherDetail({voucher,fda,caps,onBack}){
const R=useRole();
const [busy,setBusy]=useState(false);
const [upId,setUpId]=useState(null);
const fileRef=useRef(null);
const exps=voucher.expenses||[];
const t=voucherTotal(voucher,fda.roe);

/* Qualquer alteração reabre o voucher: o que foi validado foi aquele conteúdo */
const locked=isClosed(fda);
const write=async next=>{
  if(locked){ toast('Prestação finalizada — reabra para alterar','bad'); return; }
  const patch={expenses:next};
  if(voucher.status==='validated'){patch.status='pending';patch.validatedAt=null;}
  await caps.db.doc('vouchers/'+voucher.id).update(patch);
  if(voucher.status==='validated')toast('Voucher reaberto pela alteração');
};
const validado=voucher.status==='validated';
const prevUsd=Number(voucher.estimatedUsd||0);
const prevBrl=Number(voucher.estimatedBrl||0)||prevUsd*Number(fda.roe||1);
const temPrevisto=prevUsd>0;
/* Voucher trazido do PDA cujas linhas ainda estão zeradas */
const semValor=(voucher.expenses||[]).every(e=>!Number(e.brl)&&!Number(e.usd));
const aplicarPrevisto=async()=>{
  const itens=(voucher.estimatedItems&&voucher.estimatedItems.length)
    ?voucher.estimatedItems
    :(voucher.estimatedFrom||'').split(' + ').filter(Boolean).length>1
      ?null
      :[{description:voucher.estimatedFrom||voucher.accountName,brl:prevBrl,usd:prevUsd}];
  if(!itens){
    toast('Este voucher foi criado antes do detalhamento por linha — lance as despesas manualmente','bad');
    return;
  }
  const linhas=itens.map(it=>({id:uid(),date:'',description:it.description,notes:'',
    brl:Number(Number(it.brl||0).toFixed(2)),usd:Number(Number(it.usd||0).toFixed(2)),fromPda:true}));
  await write(linhas);
  toast(`${linhas.length} linha(s) preenchidas com o previsto`,'ok');
};
const setStatus=async st=>{
  if(!R.can('fda_validar'))return toast('Seu perfil não valida vouchers','bad');
  if(locked)return toast('Prestação finalizada — reabra para alterar','bad');
  await caps.db.doc('vouchers/'+voucher.id).update({status:st,
    validatedAt:st==='validated'?new Date().toISOString():null,validatedBy:st==='validated'?(R.me.id||'local'):null});
  toast(st==='validated'?'Voucher validado':'Voucher reaberto','ok');
};

const addExp=()=>write([...exps,{id:uid(),date:'',description:'',notes:'',brl:0,usd:0}]);
const upExp=(id,f,v)=>write(exps.map(e=>e.id===id?{...e,[f]:v}:e));
/* Alterar o R$ reconverte o US$ pelo ROE da prestação */
const upBrl=(id,v)=>write(exps.map(e=>e.id===id?{...e,brl:v,usd:Number((v/Number(fda.roe||1)).toFixed(2))}:e));
const delExp=async e=>{
  const ok=await ask({title:'Remover despesa',danger:true,confirmLabel:'Remover',
    message:e.description?`"${e.description}" sairá do voucher.`:'A linha será removida do voucher.'});
  if(!ok)return;
  if(e.assetId&&caps.assets){ try{await caps.assets.delete(e.assetId);}catch(err){} }
  write(exps.filter(x=>x.id!==e.id));
};

const pickFile=id=>{ setUpId(id); fileRef.current.value=''; fileRef.current.click(); };
const onFile=async ev=>{
  const file=ev.target.files&&ev.target.files[0];
  if(!file||!upId)return;
  if(!caps.assets)return toast('Upload indisponível nesta visualização','bad');
  if(file.size>20*1024*1024)return toast('O arquivo excede 20 MB','bad');
  setBusy(true);
  try{
    const r=await caps.assets.upload(file);
    await write(exps.map(e=>e.id===upId?{...e,assetId:r.id,assetName:file.name,assetType:r.contentType,assetSize:r.sizeBytes}:e));
    toast('Comprovante anexado','ok');
  }catch(err){ toast('Falha no upload: '+(err.message||err.code||err),'bad'); }
  setBusy(false); setUpId(null);
};
const removeFile=async e=>{
  const ok=await ask({title:'Remover comprovante',danger:true,confirmLabel:'Remover',message:`${e.assetName} sairá desta despesa. O arquivo continua guardado no histórico da prestação.`});
  if(!ok)return;
  try{ if(caps.assets)await caps.assets.delete(e.assetId); }catch(err){}
  write(exps.map(x=>x.id===e.id?{...x,assetId:null,assetName:null,assetType:null,assetSize:null}:x));
  toast('Comprovante removido');
};

const [invOpen,setInvOpen]=useState(false);
const exportVoucher=async()=>{
  setBusy(true);
  try{ await buildVoucherPdf({voucher,fda,caps}); }
  catch(err){ toast('Falha ao gerar o PDF: '+(err.message||err),'bad'); }
  setBusy(false);
};

const missing=exps.filter(e=>!e.assetId).length;

return(
<div className="card">
<div className="card-head">
<div>
<button className="btn btn-line btn-sm" style={{marginBottom:10}} onClick={onBack}>← Vouchers</button>
<h2>Voucher {voucher.number} · {voucher.accountName}
{validado?<span className="chip chip-ok" style={{marginLeft:10}}>Validado</span>
  :<span className="chip chip-warn" style={{marginLeft:10}}>A validar</span>}</h2>
<div className="sub">{(COA[voucher.group]||{}).label}{voucher.accountRef?' · GB Ref '+voucher.accountRef:''} — {fda.vessel} {voucher.voyage||fda.voyage}</div>
</div>
<div className="actions">
{!locked&&R.can('fda_validar')&&(validado
 ?<button className="btn btn-line btn-sm" onClick={()=>setStatus('pending')}>Reabrir</button>
 :<button className="btn btn-go btn-sm" onClick={()=>setStatus('validated')}>Validar voucher</button>)}
<button className="btn btn-line btn-sm" disabled={busy||!caps.downloads} onClick={()=>setInvOpen(true)}>
  Emitir invoice</button>
<button className="btn btn-primary btn-sm" disabled={busy||!caps.downloads} onClick={exportVoucher}>
  {busy?'Processando...':'Gerar voucher em PDF'}</button>
</div>
</div>

<input type="file" ref={fileRef} hidden accept="application/pdf,image/png,image/jpeg" onChange={onFile}/>
{locked&&<div className="note note-info">Prestação finalizada: o voucher está em modo consulta. Os comprovantes continuam abrindo normalmente.</div>}
<fieldset className="lockset" disabled={locked}>

{temPrevisto&&!validado&&(
<div className="note note-warn">
<strong>Valores vindos da cotação.</strong> Confira cada linha contra a nota, ajuste a descrição,
a data e o valor se mudou, remova o que não ocorreu e anexe o comprovante.
Depois disso, clique em <strong>Validar voucher</strong>.
<br/>Previsto: <span className="num">{fBRL(prevBrl)} · {fUSD(prevUsd)}</span>
{voucher.estimatedFrom?' — '+voucher.estimatedFrom:''}
{semValor&&<div style={{marginTop:10}}>
<button className="btn btn-line btn-sm" onClick={aplicarPrevisto}>Preencher com o previsto</button>
<span style={{marginLeft:10,fontSize:'.8rem',color:'var(--fg-muted)'}}>
  Este voucher foi aberto antes do preenchimento automático</span>
</div>}
</div>)}

{validado&&
<div className="note note-info">
Voucher conferido{voucher.validatedAt?' em '+new Date(voucher.validatedAt).toLocaleString('pt-BR'):''}.
Qualquer alteração aqui o reabre para nova conferência.
</div>}

{exps.length>0&&missing>0&&
<div className="note note-warn">
{missing} despesa(s) ainda sem comprovante anexado. O PDF é gerado assim mesmo, mas sem esses documentos.
</div>}

{exps.length===0?(
  temPrevisto
  ?<div className="empty">
   <h3>Nenhuma despesa lançada</h3>
   <p>A cotação previu {fBRL(prevBrl)} · {fUSD(prevUsd)} para esta conta.</p>
   <button className="btn btn-primary btn-sm" style={{marginTop:14}} onClick={aplicarPrevisto}>
     Preencher com o previsto</button>
   </div>
  :<Empty title="Nenhuma despesa lançada" text="Lance as despesas deste voucher e anexe o comprovante de cada uma."/>
):
<div style={{display:'flex',flexDirection:'column',gap:10}}>
{exps.map(e=>{
const auto=Number(e.brl||0)/Number(fda.roe||1);
return(
<div className="panel" key={e.id} style={{marginBottom:0}}>
<div className="grid-s">
<div className="field" style={{marginBottom:0,maxWidth:170}}><label>Data</label>
<input type="date" value={e.date||''} onChange={ev=>upExp(e.id,'date',ev.target.value)}/></div>
<div className="field" style={{marginBottom:0,gridColumn:'span 2'}}>
<label>Descrição{e.fromPda&&<span className="chip chip-mute" style={{marginLeft:8}}>da cotação</span>}</label>
<input value={e.description||''} placeholder="Ex: Invoice 072833 TESC — Wharfage"
  onChange={ev=>upExp(e.id,'description',ev.target.value)}/></div>
<div className="field" style={{marginBottom:0,maxWidth:170}}><label>Valor R$</label>
<MoneyInput value={e.brl} placeholder="0,00" onCommit={v=>upBrl(e.id,v)}/></div>
<div className="field" style={{marginBottom:0,maxWidth:170}}><label>Valor US$</label>
<MoneyInput value={e.usd===''||e.usd==null?auto:e.usd} placeholder="0,00"
  title="Convertido pelo ROE; pode ser ajustado" onCommit={v=>upExp(e.id,'usd',v)}/>
<span className="hint">ROE {fda.roe} · recalcula ao mudar o R$</span></div>
</div>
<div className="field" style={{marginBottom:0,marginTop:14}}><label>Outras informações</label>
<input value={e.notes||''} placeholder="Observação que acompanha esta despesa no PDF"
  onChange={ev=>upExp(e.id,'notes',ev.target.value)}/></div>
<div style={{display:'flex',alignItems:'center',gap:10,flexWrap:'wrap',marginTop:14,paddingTop:12,borderTop:'1px solid var(--border)'}}>
{e.assetId
 ?<>
  <span className="chip chip-ok">Comprovante</span>
  <a href="#" onClick={ev=>{ev.preventDefault();abrirComprovante(e.assetId);}}
     style={{fontSize:'.84rem',color:'var(--brand)',fontWeight:600,wordBreak:'break-all'}}>{e.assetName}</a>
  <span className="num" style={{fontSize:'.76rem',color:'var(--fg-muted)'}}>
    {e.assetSize?(e.assetSize/1024).toFixed(0)+' KB':''}</span>
  <button className="btn btn-line btn-sm" onClick={()=>pickFile(e.id)} disabled={busy}>Trocar</button>
  <button className="btn btn-bad btn-sm" onClick={()=>removeFile(e)} disabled={busy}>Remover</button>
 </>
 :<>
  <span className="chip chip-warn">Sem comprovante</span>
  <button className="btn btn-line btn-sm" onClick={()=>pickFile(e.id)} disabled={busy||!caps.assets}>
    Anexar PDF ou imagem</button>
 </>}
<button className="btn btn-bad btn-sm" style={{marginLeft:'auto'}} onClick={()=>delExp(e)}>Excluir linha</button>
</div>
</div>);})}
</div>}

<div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:14,flexWrap:'wrap',marginTop:18,paddingTop:16,borderTop:'2px solid var(--border-strong)'}}>
<button className="btn btn-line btn-sm" onClick={addExp}>Adicionar despesa</button>
<div style={{textAlign:'right'}}>
{voucher.estimatedUsd?(()=>{
  const e=Number(voucher.estimatedUsd), d=t.usd-e, pct=e?d/e*100:0;
  const cor=Math.abs(pct)<2?'var(--fg-muted)':(d>0?'var(--bad)':'var(--ok)');
  return <div style={{fontSize:'.76rem',color:'var(--fg-muted)',marginBottom:3}}>
    Previsto {fUSD(e)} · <span style={{color:cor,fontWeight:700}}>
    {(d>0?'+':'')+fUSD(d)} ({(d>0?'+':'')+pct.toFixed(1)}%)</span></div>;
})():null}
<div style={{fontSize:'.72rem',textTransform:'uppercase',letterSpacing:'.06em',color:'var(--fg-muted)',fontWeight:700}}>Total do voucher</div>
<div className="num" style={{fontSize:'1.15rem',fontWeight:700}}>{fBRL(t.brl)} · {fUSD(t.usd)}</div>
</div>
</div>

</fieldset>
{invOpen&&<InvoiceDialog voucher={voucher} fda={fda} caps={caps} onClose={()=>setInvOpen(false)}/>}
</div>);
}

/* ---------- Emissão de invoice ---------- */
function InvoiceDialog({voucher,fda,caps,onClose}){
const company=companyOf(React.useContext(CompaniesCtx),fda.companyId);
const today=new Date();
const [cur,setCur]=useState('BRL');
const [f,setF]=useState(()=>({
  place:'SÃO FRANCISCO DO SUL',
  date:today.toLocaleDateString('pt-BR'),
  number:(fda.invoiceNo||'')+' - '+voucher.number,
  client:[fda.to||'',(fda.clientAddress||'')].filter(Boolean).join('\n'),
  vessel:fda.vessel||''
}));
const [lines,setLines]=useState(()=>{
  const ex=(voucher.expenses||[]);
  if(ex.length===0)return[{id:uid(),desc:voucher.accountName,value:0}];
  return ex.map(e=>({id:uid(),desc:e.description||voucher.accountName,value:Number(e.brl||0)}));
});
const [busy,setBusy]=useState(false);
const set=(k,v)=>setF(p=>({...p,[k]:v}));
const total=lines.reduce((a,x)=>a+Number(x.value||0),0);

/* Troca de moeda reconverte os valores pelo ROE */
const switchCur=c=>{
  if(c===cur)return;
  const r=Number(fda.roe||1);
  setLines(ls=>ls.map(l=>({...l,value:Number((c==='USD'?l.value/r:l.value*r).toFixed(2))})));
  setCur(c);
};

const emit=async()=>{
  if(!f.client.trim())return toast('Informe o cliente','bad');
  if(lines.length===0)return toast('Adicione ao menos um serviço','bad');
  setBusy(true);
  try{ await buildInvoicePdf({inv:{...f,currency:cur,lines},caps,company}); onClose(); }
  catch(e){ toast('Falha ao gerar a invoice: '+(e.message||e),'bad'); }
  setBusy(false);
};

return(
<Dialog title="Emitir invoice" sub={`Voucher ${voucher.number} · ${voucher.accountName}`} onClose={onClose}>
<div className="note note-info">
Modelo Seatrade: logo, praça e data, dados do cliente, serviços e total. As linhas vêm das
despesas do voucher e podem ser reescritas — na invoice vale o texto que o cliente lê, não o
histórico interno.
</div>
<div className="grid">
<div className="field"><label>Praça</label><input value={f.place} onChange={e=>set('place',e.target.value)}/></div>
<div className="field"><label>Data</label><input value={f.date} onChange={e=>set('date',e.target.value)}/></div>
<div className="field"><label>Número da invoice</label><input value={f.number} onChange={e=>set('number',e.target.value)}/>
<span className="hint">No modelo: fatura - voucher, ex. 1279 - 1</span></div>
<div className="field"><label>Moeda</label>
<select value={cur} onChange={e=>switchCur(e.target.value)}>
<option value="BRL">BRL</option><option value="USD">USD</option></select>
<span className="hint">Converte os valores pelo ROE {fda.roe}</span></div>
</div>
<div className="field"><label>Cliente</label>
<textarea rows="5" value={f.client} onChange={e=>set('client',e.target.value)}
  placeholder={'Razão social\nRua, número\nCidade, país'}/>
<span className="hint">Primeira linha é o nome; as demais, o endereço</span></div>

<div className="panel">
<div className="panel-head"><h3>Service basis of calculation</h3></div>
{lines.map((l,i)=>(
<div key={l.id} className="ed-row c4" style={{gridTemplateColumns:'1fr 150px 38px'}}>
<input value={l.desc} placeholder="Ex: Receiving and segregation of the wireslings"
  onChange={e=>setLines(ls=>ls.map((x,j)=>j===i?{...x,desc:e.target.value}:x))}/>
<MoneyInput value={l.value} placeholder="0,00"
  onCommit={v=>setLines(ls=>ls.map((x,j)=>j===i?{...x,value:v}:x))}/>
<button type="button" className="x-btn" aria-label="Remover"
  onClick={()=>setLines(ls=>ls.filter((_,j)=>j!==i))}>×</button>
</div>))}
<div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:12,flexWrap:'wrap',marginTop:12}}>
<button type="button" className="btn btn-line btn-sm"
  onClick={()=>setLines(ls=>[...ls,{id:uid(),desc:'',value:0}])}>Adicionar serviço</button>
<div className="num" style={{fontWeight:700}}>TOTAL INVOICE &nbsp; {cur} {total.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}</div>
</div>
</div>

<div className="form-actions">
<button type="button" className="btn btn-line btn-sm" onClick={onClose}>Cancelar</button>
<button type="button" className="btn btn-primary btn-sm" disabled={busy||!caps.downloads} onClick={emit}>
  {busy?'Gerando...':'Gerar invoice em PDF'}</button>
</div>
</Dialog>);
}

/* ---------- Diálogo: cabeçalho da FDA ---------- */
function FdaHeaderDialog({fda,onSave,onClose}){
const companies=React.useContext(CompaniesCtx);
const shipowners=React.useContext(OwnersCtx)||[];
const [f,setF]=useState(()=>fda?JSON.parse(JSON.stringify(fda)):BLANK_FDA(companyOf(companies,'')));
const company=companyOf(companies,f.companyId);
const [sec,setSec]=useState('vessel');
const s=(k,v)=>setF(p=>({...p,[k]:v}));
/* escolher o armador preenche cliente, endereço, moeda e a conta de remessa dele */
const pickOwner=id=>{
  const so=shipowners.find(x=>x.id===id);
  if(!so){ s('shipownerId',''); return; }
  const co=companyOf(companies,so.companyId||f.companyId);
  setF(p=>({...p,...clientFrom(so),...remitFrom(co,ownerBankFor(so,co)),companyId:co.id}));
  toast('Dados de faturamento de '+so.name+' aplicados','ok');
};
const pickBank=id=>setF(p=>({...p,...remitFrom(company,id)}));
const pickCompany=id=>{
  const co=companyOf(companies,id);
  setF(p=>({...p,companyId:co.id,...remitFrom(co,'')}));
};
const ownerSel=shipowners.find(x=>x.id===f.shipownerId);
const semEndereco=ownerSel&&!ownerSel.billingAddress;
const adv=f.advances||[];
return(
<Dialog title={fda?'Editar cabeçalho':'Nova prestação de contas'}
  sub="Dados que aparecem na Main Cover e em cada voucher" onClose={onClose}>
<form onSubmit={e=>{e.preventDefault(); if(!f.vessel.trim())return toast('Informe o navio','bad'); onSave(f);}}>
<div className="subnav">
{[['vessel','Escala'],['invoice','Fatura e remessa']].map(([k,l])=>(
<button key={k} type="button" className={sec===k?'active':''} onClick={()=>setSec(k)}>{l}</button>))}
</div>

{sec==='vessel'&&<>
<div className="grid">
<div className="field"><label>Navio *</label><input value={f.vessel} onChange={e=>s('vessel',e.target.value)} placeholder="Ex: CANELO ARROW"/></div>
<div className="field"><label>Viagem</label><input value={f.voyage} onChange={e=>s('voyage',e.target.value)} placeholder="Ex: 2509"/></div>
<div className="field"><label>Porto</label><input value={f.port} onChange={e=>s('port',e.target.value)} placeholder="Ex: São Francisco do Sul/Brazil"/></div>
<div className="field"><label>ROE · câmbio da prestação</label><input type="number" step="0.0001" value={f.roe} onChange={e=>s('roe',Number(e.target.value)||0)}/></div>
</div>
<div className="grid">
<div className="field"><label>Procedência</label><input value={f.arrivedFrom} onChange={e=>s('arrivedFrom',e.target.value)}/></div>
<div className="field"><label>Chegada</label><input value={f.arrivedAt} onChange={e=>s('arrivedAt',e.target.value)} placeholder="January 03 at 03:24 hrs"/></div>
<div className="field"><label>Destino</label><input value={f.sailedTo} onChange={e=>s('sailedTo',e.target.value)}/></div>
<div className="field"><label>Saída</label><input value={f.sailedAt} onChange={e=>s('sailedAt',e.target.value)} placeholder="January 06 at 11:18 hrs"/></div>
</div>
<div className="grid-s">
<div className="field"><label>GRT</label><input type="number" value={f.grt||''} onChange={e=>s('grt',Number(e.target.value)||0)}/></div>
<div className="field"><label>DWT</label><input type="number" value={f.dwt||''} onChange={e=>s('dwt',Number(e.target.value)||0)}/></div>
<div className="field"><label>LOA</label><input type="number" step="0.01" value={f.loa||''} onChange={e=>s('loa',Number(e.target.value)||0)}/></div>
<div className="field"><label>Beam</label><input type="number" step="0.01" value={f.beam||''} onChange={e=>s('beam',Number(e.target.value)||0)}/></div>
<div className="field"><label>Depth / Draft</label><input value={f.draft||''} onChange={e=>s('draft',e.target.value)}/></div>
</div>
<div className="grid">
<div className="field"><label>Loaded qty / unit</label><input value={f.loadedQty} onChange={e=>s('loadedQty',e.target.value)}/></div>
<div className="field"><label>Discharge qty / unit</label><input value={f.dischargeQty} onChange={e=>s('dischargeQty',e.target.value)}/></div>
</div>
<div className="field"><label>Remarks</label><input value={f.remarks} onChange={e=>s('remarks',e.target.value)}/></div>
</>}

{sec==='invoice'&&<>
<div className="grid">
{companies.length>1&&
<div className="field"><label>Empresa emitente</label>
<select value={f.companyId||company.id} onChange={e=>pickCompany(e.target.value)}>
{companies.map(c=><option key={c.id} value={c.id}>{c.tradeName||c.legalName}</option>)}</select>
<span className="hint">Logo dos documentos e conta de remessa</span></div>}
<div className="field"><label>Armador cadastrado</label>
<select value={f.shipownerId||''} onChange={e=>pickOwner(e.target.value)}>
<option value="">— digitar manualmente —</option>
{shipowners.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select>
<span className="hint">{semEndereco?'Este armador está sem endereço de faturamento no cadastro'
  :'Preenche cliente, endereço, moeda e conta de remessa'}</span></div>
<div className="field"><label>Cliente (To)</label><input value={f.to} onChange={e=>s('to',e.target.value)} placeholder="Ex: Armador Exemplo AS"/></div>
<div className="field"><label>Invoice nº / referência do agente</label><input value={f.invoiceNo} onChange={e=>s('invoiceNo',e.target.value)}/></div>
<div className="field"><label>Data da fatura</label><input type="date" value={f.invoiceDate||''} onChange={e=>s('invoiceDate',e.target.value)}/></div>
<div className="field"><label>Moeda</label><select value={f.currency} onChange={e=>s('currency',e.target.value)}>
<option value="USD">USD</option><option value="BRL">BRL</option></select></div>
</div>
<div className="field"><label>Endereço do cliente — usado nas invoices</label>
<textarea rows="4" value={f.clientAddress||''} onChange={e=>s('clientAddress',e.target.value)}
  placeholder={'Rua, número\nCidade, país\nTax ID'}/>
<span className="hint">Uma linha por linha do endereço, como deve sair impresso</span></div>
<div className="panel">
<div className="panel-head"><h3>Dados para remessa</h3>
<div className="actions" style={{alignItems:'center'}}>
<select className="inp" style={{width:'auto',padding:'6px 10px',fontSize:'.8rem'}}
  value={f.bankAccountId||''} onChange={e=>pickBank(e.target.value)}>
<option value="" disabled>Conta da empresa…</option>
{((company||{}).bankAccounts||[]).map(b=><option key={b.id} value={b.id}>{b.label||b.bank}{b.isDefault?' (padrão)':''}</option>)}
</select>
<button type="button" className="btn btn-line btn-sm" onClick={()=>pickBank(f.bankAccountId)}>Recarregar da empresa</button>
</div></div>
<div className="grid">
<div className="field" style={{marginBottom:0}}><label>Agente / fornecedor</label><input value={f.agent} onChange={e=>s('agent',e.target.value)}/></div>
<div className="field" style={{marginBottom:0}}><label>Endereço</label><input value={f.agentAddress} onChange={e=>s('agentAddress',e.target.value)}/></div>
<div className="field" style={{marginBottom:0}}><label>Favorecido</label><input value={f.remitTo} onChange={e=>s('remitTo',e.target.value)}/></div>
<div className="field" style={{marginBottom:0}}><label>Banco e agência</label><input value={f.bank} onChange={e=>s('bank',e.target.value)}/></div>
<div className="field" style={{marginBottom:0}}><label>Conta</label><input value={f.account} onChange={e=>s('account',e.target.value)}/></div>
<div className="field" style={{marginBottom:0}}><label>IBAN / SWIFT</label><input value={f.swift} onChange={e=>s('swift',e.target.value)}/></div>
</div></div>
</>}

<div className="form-actions">
<button type="button" className="btn btn-line btn-sm" onClick={onClose}>Cancelar</button>
<button type="submit" className="btn btn-primary btn-sm">Salvar</button>
</div>
</form></Dialog>);
}

/* ---------- Diálogo: novo voucher ---------- */
function VoucherDialog({existing,onSave,onClose}){
const next=existing.reduce((a,v)=>Math.max(a,Number(v.number)||0),0)+1;
const [group,setGroup]=useState('port');
const [idx,setIdx]=useState('');
const [custom,setCustom]=useState('');
const [number,setNumber]=useState(next);
const items=(COA[group]||{items:[]}).items;

const submit=e=>{
  e.preventDefault();
  const picked=idx===''?null:items[Number(idx)];
  const name=picked?picked.name:custom.trim();
  if(!name)return toast('Escolha a conta ou escreva a descrição','bad');
  if(!number)return toast('Informe o número do voucher','bad');
  if(existing.some(v=>Number(v.number)===Number(number)))return toast('Já existe um voucher com esse número','bad');
  onSave({number:Number(number),group,accountRef:picked?picked.ref:'',accountName:name});
};

return(
<Dialog size="sm" title="Novo voucher" sub="Escolha a conta do plano do armador" onClose={onClose}>
<form onSubmit={submit}>
<div className="grid">
<div className="field"><label>Número do voucher *</label>
<input type="number" value={number} onChange={e=>setNumber(e.target.value)}/>
<span className="hint">É este número que a cover referencia</span></div>
<div className="field"><label>Grupo de despesa *</label>
<select value={group} onChange={e=>{setGroup(e.target.value);setIdx('');}}>
{GROUP_ORDER.map(g=><option key={g} value={g}>{COA[g].label}</option>)}</select></div>
</div>
<div className="field"><label>Conta</label>
<select value={idx} onChange={e=>setIdx(e.target.value)}>
<option value="">Outra — descrever manualmente</option>
{items.map((it,i)=><option key={i} value={i}>{it.ref?it.ref+' — ':''}{it.name}</option>)}</select></div>
{idx===''&&
<div className="field"><label>Descrição da conta *</label>
<input value={custom} onChange={e=>setCustom(e.target.value)} placeholder="Ex: Shore Crane"/>
<span className="hint">Equivale às linhas marcadas com (*) no template do armador</span></div>}
<div className="form-actions">
<button type="button" className="btn btn-line btn-sm" onClick={onClose}>Cancelar</button>
<button type="submit" className="btn btn-primary btn-sm">Criar voucher</button>
</div>
</form></Dialog>);
}

/* ============================================================
   GERAÇÃO DE PDF — pdf-lib
   O voucher sai com os comprovantes anexados em seguida
   ============================================================ */
const A4=[595.28,841.89];
const M=42;

async function pdfDoc(withLogo,companyId){
  if(!window.PDFLib)throw new Error('biblioteca de PDF não carregou');
  const doc=await window.PDFLib.PDFDocument.create();
  const font=await doc.embedFont(window.PDFLib.StandardFonts.Helvetica);
  const bold=await doc.embedFont(window.PDFLib.StandardFonts.HelveticaBold);
  let logo=null;
  if(withLogo!==false)logo=await embedLogoFor(doc,companyId);
  return{doc,font,bold,rgb:window.PDFLib.rgb,logo};
}
const clip=(s,font,size,max)=>{
  let t=String(s==null?'':s);
  while(t.length>1&&font.widthOfTextAtSize(t,size)>max)t=t.slice(0,-1);
  return t;
};
/* Agrupa as linhas da cotação pelo plano de contas do armador */
function groupByAccount(lines){
  const map={};
  lines.forEach(l=>{
    const ref=l.acct||ACCT.customs;
    const g=acctGroupOf(ref);
    const k=g+'|'+ref;
    if(!map[k])map[k]={group:g,ref,name:acctName(ref,g)||ref,local:isLocalAcct(ref),usd:0,native:0,from:[],items:[]};
    map[k].usd+=l.usd||0;
    map[k].native+=(l.currency==='BRL'?(l.native||0):0);
    map[k].from.push(l.label);
    map[k].items.push({label:l.label,usd:l.usd||0,native:l.native,currency:l.currency||'USD',note:l.note||''});
  });
  return GROUP_ORDER.flatMap(g=>Object.values(map).filter(x=>x.group===g));
}

const moneyBR=n=>Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
const money=(n,d)=>Number(n||0).toLocaleString('en-US',{minimumFractionDigits:d===undefined?2:d,maximumFractionDigits:d===undefined?2:d});

function header(page,{font,bold,rgb,logo},fda,title,sub){
  const W=A4[0];
  const top=A4[1]-M;
  /* Faixa da marca: logo à direita, identificação à esquerda, régua abaixo de ambos */
  const bandH=52;
  let logoW=0;
  if(logo){
    logoW=logo.width*bandH/logo.height;
    page.drawImage(logo,{x:W-M-logoW,y:top-bandH+6,width:logoW,height:bandH});
  }
  const textW=W-2*M-(logoW?logoW+16:0);
  page.drawText(clip(fda.agent||'Agência marítima',bold,11,textW),
    {x:M,y:top-15,size:11,font:bold,color:rgb(0.09,0.29,0.38)});
  if(fda.agentAddress)
    page.drawText(clip(fda.agentAddress,font,8,textW),{x:M,y:top-28,size:8,font,color:rgb(.42,.48,.53)});
  const ruleY=top-bandH;
  page.drawLine({start:{x:M,y:ruleY},end:{x:W-M,y:ruleY},thickness:1.2,color:rgb(0.09,0.29,0.38)});
  let y=ruleY-22;
  page.drawText(title,{x:M,y,size:14,font:bold,color:rgb(.08,.13,.17)});
  if(sub){page.drawText(clip(sub,font,9,W-2*M),{x:M,y:y-13,size:9,font,color:rgb(.42,.48,.53)});}
  y-=32;
  const pairs=[['Navio',fda.vessel],['Viagem',fda.voyage],['Porto',fda.port],
    ['Chegada',fda.arrivedAt],['Saída',fda.sailedAt],['ROE',String(fda.roe)]];
  const colW=(W-2*M)/3;
  pairs.forEach((p,i)=>{
    const col=i%3, row=Math.floor(i/3);
    const x=M+col*colW, yy=y-row*26;
    page.drawText(p[0].toUpperCase(),{x,y:yy,size:6.5,font:bold,color:rgb(.55,.6,.65)});
    page.drawText(clip(p[1]||'—',font,9,colW-10),{x,y:yy-11,size:9,font,color:rgb(.08,.13,.17)});
  });
  return y-26*Math.ceil(pairs.length/3)-10;
}

function tableHead(page,{bold,rgb},y,cols){
  const W=A4[0];
  page.drawRectangle({x:M,y:y-4,width:W-2*M,height:18,color:rgb(.91,.94,.96)});
  cols.forEach(c=>page.drawText(c.label,{x:c.align==='r'?c.x+c.w-c.label.length*4.2:c.x,y:y+2,size:7,font:bold,color:rgb(.33,.41,.48)}));
  return y-14;
}

/* Desenha as páginas de um voucher (sem os anexos) no documento dado */
function drawVoucher(doc,K,fda,voucher){
  const {font,bold,rgb}=K; const W=A4[0];
  let page=doc.addPage(A4);
  let y=header(page,K,fda,'VOUCHER '+voucher.number,
    (voucher.accountRef?voucher.accountRef+' · ':'')+voucher.accountName+' — '+(COA[voucher.group]||{}).label);
  const cols=[{label:'DATA',x:M,w:62},{label:'DESCRIÇÃO',x:M+68,w:W-2*M-68-150},
    {label:'R$',x:W-M-150,w:72,align:'r'},{label:'US$',x:W-M-74,w:74,align:'r'}];
  y=tableHead(page,K,y,cols);
  let tb=0,tu=0;
  for(const e of (voucher.expenses||[])){
    const extra=(e.notes?10:0)+(e.assetName?9:0);
    if(y<80+extra){ page=doc.addPage(A4); y=A4[1]-M-10; y=tableHead(page,K,y,cols); }
    const u=(e.usd===''||e.usd===undefined||e.usd===null)?Number(e.brl||0)/Number(fda.roe||1):Number(e.usd);
    tb+=Number(e.brl||0); tu+=u;
    page.drawText(e.date?new Date(e.date+'T00:00:00').toLocaleDateString('pt-BR'):'—',
      {x:cols[0].x,y,size:8,font,color:rgb(.08,.13,.17)});
    page.drawText(clip(e.description||'—',font,8,cols[1].w),{x:cols[1].x,y,size:8,font,color:rgb(.08,.13,.17)});
    const b1=money(e.brl),u1=money(u);
    page.drawText(b1,{x:cols[2].x+cols[2].w-font.widthOfTextAtSize(b1,8),y,size:8,font});
    page.drawText(u1,{x:cols[3].x+cols[3].w-font.widthOfTextAtSize(u1,8),y,size:8,font});
    let dy=15;
    if(e.notes){
      page.drawText(clip(e.notes,font,7.5,cols[1].w),{x:cols[1].x,y:y-9,size:7.5,font,color:rgb(.33,.41,.48)});
      dy+=10;
    }
    if(e.assetName){
      page.drawText(clip('anexo: '+e.assetName,font,6.5,cols[1].w),
        {x:cols[1].x,y:y-(e.notes?19:8),size:6.5,font,color:rgb(.5,.56,.62)});
      dy+=9;
    }
    y-=dy;
  }
  y-=4;
  page.drawLine({start:{x:M,y:y+6},end:{x:W-M,y:y+6},thickness:1,color:rgb(.09,.29,.38)});
  page.drawText('TOTAL',{x:M,y:y-6,size:9,font:bold});
  const tbs=money(tb),tus=money(tu);
  page.drawText(tbs,{x:cols[2].x+cols[2].w-bold.widthOfTextAtSize(tbs,9),y:y-6,size:9,font:bold});
  page.drawText(tus,{x:cols[3].x+cols[3].w-bold.widthOfTextAtSize(tus,9),y:y-6,size:9,font:bold});
}

/* Anexa os comprovantes de um voucher logo após suas páginas */
async function attachDocs(doc,voucher){
  let ok=0,fail=0;
  for(const e of (voucher.expenses||[])){
    if(!e.assetId)continue;
    try{
      const res=await baixarComprovante(e.assetId);
      if(!res.ok)throw new Error(res.status);
      const buf=await res.arrayBuffer();
      const type=(e.assetType||'').toLowerCase();
      if(type.includes('pdf')){
        const src=await window.PDFLib.PDFDocument.load(buf,{ignoreEncryption:true});
        const pages=await doc.copyPages(src,src.getPageIndices());
        pages.forEach(p=>doc.addPage(p));
      }else{
        const img=type.includes('png')?await doc.embedPng(buf):await doc.embedJpg(buf);
        const p=doc.addPage(A4);
        const sc=Math.min((A4[0]-2*M)/img.width,(A4[1]-2*M)/img.height,1);
        p.drawImage(img,{x:(A4[0]-img.width*sc)/2,y:(A4[1]-img.height*sc)/2,
          width:img.width*sc,height:img.height*sc});
      }
      ok++;
    }catch(err){ fail++; }
  }
  return{ok,fail};
}

async function buildVoucherPdf({voucher,fda,caps}){
  const K=await pdfDoc(true,fda.companyId); const {doc}=K;
  drawVoucher(doc,K,fda,voucher);
  const r=await attachDocs(doc,voucher);
  const bytes=await doc.save();
  const name=`Voucher ${voucher.number} - ${(fda.vessel||'navio').replace(/[^\w\s-]/g,'')} ${fda.voyage||''} - ${voucher.accountName.replace(/[^\w\s-]/g,'')}.pdf`.replace(/\s+/g,' ').trim();
  const out=await caps.downloads.save({filename:name,data:new Blob([bytes],{type:'application/pdf'})});
  if(out&&out.status==='saved')
    toast(r.ok?`Voucher gerado com ${r.ok} comprovante(s)`+(r.fail?` · ${r.fail} falharam`:''):'Voucher gerado','ok');
}

async function buildFdaPdf({fda,vouchers,rows,subBrl,subUsd,advBrl,advUsd,dueBrl,dueUsd,caps,withDocs}){
  const K=await pdfDoc(true,fda.companyId); const {doc,font,bold,rgb}=K;
  const W=A4[0];
  let page=doc.addPage(A4);
  let y=header(page,K,fda,'FINAL DISBURSEMENT ACCOUNT',
    (fda.to?'Para: '+fda.to+' · ':'')+'Invoice '+(fda.invoiceNo||'—'));

  /* cliente */
  const cli=[fda.to||'',...String(fda.clientAddress||'').split('\n')].filter(x=>x.trim());
  if(cli.length){
    page.drawText('TO:',{x:M,y,size:8,font:bold,color:rgb(.42,.48,.53)});
    cli.slice(0,6).forEach((l,i)=>page.drawText(clip(l,i?font:bold,8.5,W/2),{x:M+28,y:y-i*11,size:8.5,font:i?font:bold}));
    y-=Math.min(cli.length,6)*11+10;
  }
  page.drawText('MAIN COVER',{x:M,y,size:9,font:bold,color:rgb(.09,.29,.38)}); y-=16;
  const c=[{label:'EXPENSE TYPE',x:M,w:220},{label:'LOCAL CURRENCY',x:W-M-280,w:120,align:'r'},
    {label:'ROE',x:W-M-152,w:52,align:'r'},{label:'USD',x:W-M-96,w:96,align:'r'}];
  y=tableHead(page,K,y,c);
  const put=(label,brl,roe,usd,b)=>{
    const f2=b?bold:font;
    page.drawText(label,{x:c[0].x,y,size:8,font:f2});
    const a1=money(brl);page.drawText(a1,{x:c[1].x+c[1].w-f2.widthOfTextAtSize(a1,8),y,size:8,font:f2});
    if(roe!==null){const r2=String(roe);page.drawText(r2,{x:c[2].x+c[2].w-f2.widthOfTextAtSize(r2,8),y,size:8,font:f2,color:rgb(.45,.52,.58)});}
    const d1=money(usd);page.drawText(d1,{x:c[3].x+c[3].w-f2.widthOfTextAtSize(d1,8),y,size:8,font:f2});
    y-=14;
  };
  rows.forEach(r=>put(r.label,r.brl,fda.roe,r.usd,false));
  page.drawLine({start:{x:M,y:y+9},end:{x:W-M,y:y+9},thickness:.8,color:rgb(.7,.78,.84)});
  put('Sub Total',subBrl,null,subUsd,true);
  (fda.advances||[]).forEach(a=>put('Less Advance'+(a.label?' · '+a.label:''),-Number(a.brl||0),a.roe||fda.roe,-Number(a.brl||0)/Number(a.roe||fda.roe||1),false));
  page.drawRectangle({x:M,y:y-4,width:W-2*M,height:17,color:rgb(.86,.92,.95)});
  put('TOTAL DUE',dueBrl,null,dueUsd,true);

  /* dados para remessa — o que o armador precisa para pagar */
  const rem=[['Please remit to',fda.remitTo],['Bank',fda.bank],['Account',fda.account],
    ['IBAN / Swift',fda.swift],['Currency',fda.currency==='BRL'?'R$ (Brazilian Real)':'US$ (American Dollar)']].filter(r=>r[1]);
  if(rem.length){
    y-=18;
    page.drawText('REMITTANCE DETAILS',{x:M,y,size:9,font:bold,color:rgb(.09,.29,.38)}); y-=14;
    rem.forEach(([k,val])=>{
      page.drawText(k+':',{x:M,y,size:8,font:bold,color:rgb(.42,.48,.53)});
      page.drawText(clip(String(val),font,8.5,W-2*M-110),{x:M+110,y,size:8.5,font});
      y-=12;
    });
    page.drawText('Please always put the vessel name on remittance to ensure proper credit.',
      {x:M,y:y-4,size:7.5,font,color:rgb(.42,.48,.53)});
  }

  const byG={};
  vouchers.forEach(v=>{(byG[v.group]=byG[v.group]||[]).push(v);});
  for(const g of GROUP_ORDER){
    const vs=byG[g]; if(!vs||!vs.length)continue;
    page=doc.addPage(A4); y=A4[1]-M;
    page.drawText(COA[g].label.toUpperCase()+' — EXPENSES COVER',{x:M,y,size:11,font:bold,color:rgb(.09,.29,.38)});
    page.drawText(clip((fda.vessel||'')+'  ·  '+(fda.voyage||''),font,8,300),{x:M,y:y-13,size:8,font,color:rgb(.42,.48,.53)});
    y-=34;
    const cc=[{label:'GB REF',x:M,w:60},{label:'CONTA',x:M+68,w:200},{label:'VOUCHER',x:W-M-290,w:54,align:'r'},
      {label:'LOCAL CURRENCY',x:W-M-232,w:118,align:'r'},{label:'USD',x:W-M-108,w:108,align:'r'}];
    y=tableHead(page,K,y,cc);
    let gb=0,gu=0;
    for(const v of vs){
      if(y<80){page=doc.addPage(A4);y=A4[1]-M-10;y=tableHead(page,K,y,cc);}
      const t=voucherTotal(v,fda.roe); gb+=t.brl; gu+=t.usd;
      page.drawText(v.accountRef||'—',{x:cc[0].x,y,size:7.5,font,color:rgb(.45,.52,.58)});
      page.drawText(clip(v.accountName,font,8,cc[1].w),{x:cc[1].x,y,size:8,font});
      const nv=String(v.number);
      page.drawText(nv,{x:cc[2].x+cc[2].w-font.widthOfTextAtSize(nv,8),y,size:8,font});
      const a2=money(t.brl);page.drawText(a2,{x:cc[3].x+cc[3].w-font.widthOfTextAtSize(a2,8),y,size:8,font});
      const d2=money(t.usd);page.drawText(d2,{x:cc[4].x+cc[4].w-font.widthOfTextAtSize(d2,8),y,size:8,font});
      y-=14;
    }
    page.drawLine({start:{x:M,y:y+9},end:{x:W-M,y:y+9},thickness:.8,color:rgb(.7,.78,.84)});
    page.drawText('Total '+COA[g].label,{x:cc[0].x,y:y-3,size:8,font:bold});
    const a3=money(gb);page.drawText(a3,{x:cc[3].x+cc[3].w-bold.widthOfTextAtSize(a3,8),y:y-3,size:8,font:bold});
    const d3=money(gu);page.drawText(d3,{x:cc[4].x+cc[4].w-bold.widthOfTextAtSize(d3,8),y:y-3,size:8,font:bold});
  }

  /* Vouchers, na ordem do número */
  const ordered=vouchers.slice().sort((x,z)=>Number(x.number||0)-Number(z.number||0));
  let docsOk=0,docsFail=0;
  for(const v of ordered){
    drawVoucher(doc,K,fda,v);
    if(withDocs){ const r=await attachDocs(doc,v); docsOk+=r.ok; docsFail+=r.fail; }
  }

  const bytes=await doc.save();
  const name=`FDA - ${(fda.vessel||'navio').replace(/[^\w\s-]/g,'')} ${fda.voyage||''} - ${fda.port||''}.pdf`.replace(/\s+/g,' ').trim();
  const out=await caps.downloads.save({filename:name,data:new Blob([bytes],{type:'application/pdf'})});
  if(out&&out.status==='saved')
    toast(`FDA gerada com ${ordered.length} voucher(s)`+(withDocs?` e ${docsOk} comprovante(s)`:'')+(docsFail?` · ${docsFail} falharam`:''),'ok');
  return !!(out&&out.status==='saved')&&!docsFail;
}


/* ============================================================
   INVOICE — modelo Seatrade
   ============================================================ */
const SEATRADE_BRANCHES=[];

const b64bytes=b64=>{
  const bin=atob(b64); const u=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i);
  return u;
};
let _logo=null,_wm=null;
async function embedLogo(doc){ return doc.embedPng(b64bytes(LOGO_B64)); }
async function embedWm(doc){ return doc.embedPng(b64bytes(WM_B64)); }

async function buildInvoicePdf({inv,caps,company}){
  const K=await pdfDoc(); const {doc,font,bold,rgb}=K;
  const W=A4[0],H=A4[1];
  const BLUE=rgb(.12,.27,.47), BLACK=rgb(.1,.1,.1);
  const page=doc.addPage(A4);

  // logo
  const logo=await embedLogoFor(doc,(company||{}).id);
  const lw=168, lh=logo?logo.height*lw/logo.width:0;
  if(logo)page.drawImage(logo,{x:(W-lw)/2,y:H-54-lh,width:lw,height:lh});
  else page.drawText((company||{}).legalName||'',{x:M,y:H-70,size:13,font:bold,color:rgb(.12,.27,.47)});

  const L=M, R=W-M, SPLIT=W-M-176;
  let y=H-54-lh-34;
  const line=(x1,y1,x2,y2)=>page.drawLine({start:{x:x1,y:y1},end:{x:x2,y:y2},thickness:1,color:BLACK});
  const center=(t,x1,x2,yy,size,f,color)=>{
    const w=f.widthOfTextAtSize(t,size);
    page.drawText(t,{x:x1+(x2-x1-w)/2,y:yy,size,font:f,color:color||BLUE});
  };

  // faixa 1: praça/data | número
  const H1=28; const top=y;
  line(L,top,R,top); line(L,top-H1,R,top-H1);
  line(L,top,L,top-H1); line(R,top,R,top-H1); line(SPLIT,top,SPLIT,top-H1);
  center((inv.place||'SÃO FRANCISCO DO SUL')+', '+inv.date,L,SPLIT,top-19,13,font,BLUE);
  center('INVOICE '+inv.number,SPLIT,R,top-19,12,bold,BLUE);
  y=top-H1;

  // bloco do cliente
  const HC=168;
  line(L,y-HC,R,y-HC); line(L,y,L,y-HC); line(R,y,R,y-HC); line(SPLIT,y,SPLIT,y-HC);
  page.drawText('CLIENT:',{x:L+9,y:y-18,size:10,font:bold,color:BLUE});
  let cy=y-44;
  (inv.client||'').split('\n').slice(0,8).forEach(l=>{
    page.drawText(clip(l,font,10.5,SPLIT-L-18),{x:L+9,y:cy,size:10.5,font,color:BLUE});
    cy-=15;
  });
  y-=HC;

  // cabeçalho da tabela
  const H2=20;
  line(L,y-H2,R,y-H2); line(L,y,L,y-H2); line(R,y,R,y-H2); line(SPLIT,y,SPLIT,y-H2);
  center('SERVICE BASIS OF CALCULATION',L,SPLIT,y-14,9,bold,BLUE);
  center('VALUE ('+inv.currency+')',SPLIT,R,y-14,10,bold,BLUE);
  y-=H2;

  // corpo com marca d'água
  const bodyTop=y, HB=Math.max(300,38+inv.lines.length*30);
  const wm=await embedWm(doc);
  const ww=Math.min(R-L-20,430), wh=wm.height*ww/wm.width;
  page.drawImage(wm,{x:(W-ww)/2,y:bodyTop-HB/2-wh/2,width:ww,height:wh,opacity:.5});

  let ly=bodyTop-34;
  inv.lines.forEach(it=>{
    page.drawCircle({x:L+26,y:ly+3,size:1.7,color:BLACK});
    page.drawText(clip(it.desc||'—',font,9.5,SPLIT-L-56),{x:L+38,y:ly,size:9.5,font,color:BLACK});
    const v=inv.currency+' '+moneyBR(it.value);
    center(v,SPLIT,R,ly,11,font,BLACK);
    ly-=30;
  });
  line(L,bodyTop-HB,R,bodyTop-HB);
  line(L,bodyTop,L,bodyTop-HB); line(R,bodyTop,R,bodyTop-HB); line(SPLIT,bodyTop,SPLIT,bodyTop-HB);
  y=bodyTop-HB;

  // total
  const H3=26;
  line(L,y-H3,R,y-H3); line(L,y,L,y-H3); line(R,y,R,y-H3); line(SPLIT,y,SPLIT,y-H3);
  const total=inv.lines.reduce((a,x)=>a+Number(x.value||0),0);
  center('TOTAL  INVOICE',L,SPLIT,y-18,13,bold,BLUE);
  center(inv.currency+' '+moneyBR(total),SPLIT,R,y-18,13,bold,BLUE);

  // rodapé
  const fy=58;
  page.drawLine({start:{x:L,y:fy+26},end:{x:R,y:fy+26},thickness:.7,color:rgb(.45,.45,.45)});
  const span=R-L, frac=[.40,.26,.34];
  let fx=L;
  const brs=((company&&company.branches)||[]).filter(b=>b.title).map(b=>({t:b.title,l:(b.lines||[]).filter(Boolean)}));
  const lista=brs.length?brs:SEATRADE_BRANCHES;
  const fr=lista.length===3?frac:lista.map(()=>1/lista.length);
  lista.forEach((b,i)=>{
    const colw=span*fr[i];
    page.drawText(clip(b.t,bold,5.4,colw-6),{x:fx,y:fy+16,size:5.4,font:bold,color:rgb(.15,.15,.15)});
    b.l.forEach((t,j)=>page.drawText(clip(t,font,4.8,colw-4),{x:fx,y:fy+8-j*7,size:4.8,font,color:rgb(.3,.3,.3)}));
    fx+=colw;
  });

  const bytes=await doc.save();
  const name=`Invoice ${String(inv.number).replace(/[^\w-]/g,'')} - ${(inv.vessel||'').replace(/[^\w\s-]/g,'')}.pdf`.replace(/\s+/g,' ').trim();
  const out=await caps.downloads.save({filename:name,data:new Blob([bytes],{type:'application/pdf'})});
  if(out&&out.status==='saved')toast('Invoice gerada','ok');
}

/* ============================================================
   PDA NO FORMATO DO CLIENTE — mesma estrutura para tela e PDF
   ============================================================ */
const CARGO_EN={gran_sol:'Dry Bulk Cargo',gran_liq:'Liquid Bulk Cargo',cg_solta:'General / Project Cargo',
  cg_cont:'Containerized Cargo',petroleo:'Oil & Derivatives',roro:'Ro-Ro Cargo',
  passageiro:'Passengers / Cruise',perigosa:'Dangerous Cargo',outros:'No Cargo / Other'};
const SEATRADE_BANK=[];
const MES=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const dEN=d=>{ if(!d)return'—'; const p=String(d).split('-'); return p.length===3?`${p[2]}-${MES[Number(p[1])-1]}-${p[0].slice(2)}`:d; };
const nBR=(n,dec)=>Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:dec,maximumFractionDigits:dec});

/* Agrupa as linhas por rubrica do PDA, somando BRL nativo quando a despesa é em real
   (evita o arredondamento ida-e-volta pelo câmbio). */
/* Sequência do PDA da Seatrade (modelo 091/2026). Taxas da cidade e fornecedores
   trazem a própria posição (pdaSeq); custos adicionais de terminal vêm por último. */
const PDA_SEQ={pilotage:10,shifting:15,tuf:30,ac:40,wf:50,wm:70,fb:110};
const seqOf=l=>l.pdaSeq!=null?l.pdaSeq:(PDA_SEQ[l.pdaKey]!=null?PDA_SEQ[l.pdaKey]:130);
function pdaGroups(lines,fx){
  const out=[],idx={};
  [...lines].map((l,i)=>({l,i})).sort((a,b)=>(seqOf(a.l)-seqOf(b.l))||(a.i-b.i)).map(x=>x.l).forEach(l=>{
    const k=l.pdaKey||l.key;
    if(idx[k]===undefined){ idx[k]=out.length; out.push({key:k,label:l.pdaLabel||l.label,comment:l.comment||'',usd:0,brl:0}); }
    const r=out[idx[k]];
    const brl=l.currency==='BRL'?Number(l.native||0):Number(l.usd||0)*fx;
    r.brl+=brl; r.usd+=l.currency==='BRL'?brl/fx:Number(l.usd||0);
  });
  return out;
}

function pdaModel(res,r,company){
  const v=res.vessel, fx=Number(v.exchangeRate)||1, port=res.port||{};
  const term=(r.terminal||'')+(r.type==='public'?' - PUBLIC QUAY':'');
  const rate=(((port.access_channel||{}).rates)||[]).find(x=>x.id===v.cargoType);
  const port_=pdaGroups(r.portCosts,fx), ag=pdaGroups(r.agency,fx), gv=pdaGroups(r.gov,fx);
  /* comentário ajustado na folha deste PDA prevalece sobre o do cadastro */
  const ov=r.pdaComments||{};
  [port_,ag,gv].forEach(list=>list.forEach(x=>{ if(ov[x.key]!==undefined)x.comment=ov[x.key]; }));
  const sum=a=>a.reduce((t,x)=>({usd:t.usd+x.usd,brl:t.brl+x.brl}),{usd:0,brl:0});
  const sP=sum(port_), sA=sum(ag), sG=sum(gv);
  const vesselLbl=(v.name||'TBN')+(v.voy?' - '+v.voy:'');
  return{
    title:`${(port.city||'').toUpperCase()} - ${term.toUpperCase()} - ESTIMATED COSTS`,
    left:[
      ["VESSEL'S NAME - VOY",vesselLbl],['FLAG',v.flag||'TBI'],
      ['LOA',nBR(v.loa,2)],['GROSS TONNAGE',nBR(v.grossTonnage,0)],
      ['DEAD-WEIGHT',nBR(v.deadWeight,0)],['BEAM',v.beam?nBR(v.beam,2):'TBC'],
      ['PORT STAY',String(v.portStay||'')],
      ['TYPE OF CARGO',(CARGO_EN[v.cargoType]||(rate||{}).name||'—')+(v.navigation==='cabotagem'?' - CABOTAGE':'')],
      ['GOODS',(v.goods||'—').toUpperCase()],['QUANTITY',v.quantity||'—'],
      ['OPERATION',(OPS[v.operation]||'—').toUpperCase()],['TERMINAL',term.toUpperCase()]
    ],
    right:[
      ['PROFORMA NO.',v.proformaNo||'—'],['ETA',v.eta||'To Inform'],
      ['CONTACT',v.contact||'—'],['E-MAIL',v.email||(company||{}).email||'—'],
      ['PREPARED BY',v.preparedBy||'—'],['ISSUED ON',dEN(v.pdaDate)],
      ['ROE - EPDA',nBR(fx,4)],['DATE',dEN(v.pdaDate)],
      [`${(r.terminal||'').toUpperCase()} - ESTIMATED`,`Estimated Port Stay: ${v.portStay||''} Days`]
    ],
    sections:[
      {title:'PORT COSTS',rows:port_,subtotal:{label:'PORT COSTS SUB-TOTAL',...sP}},
      {title:'AGENCY CHARGES',rows:ag,subtotal:{label:'AGENCY CHARGES SUB-TOTAL',...sA}}
    ],
    tail:gv,
    total:{label:'TOTAL ESTIMATED COSTS',usd:sP.usd+sA.usd+sG.usd,brl:sP.brl+sA.brl+sG.brl},
    remarks:String(v.remarks||'').trim(),
    note:'** Indicative rate for information only. This is subject to change acc to daily rate fluctuation.',
    bank:company?bankRows(company,ownerBankFor(res.shipowner,company)):SEATRADE_BANK,
    companyId:(company||{}).id,
    file:`${v.proformaNo||'PDA'} - ${vesselLbl} - ${r.terminal} - ${dEN(v.pdaDate)}`
  };
}

