<tbody>
{m.tail.map((x,i)=><Row key={i} x={x} cls="pd-tail"/>)}
<tr className="pd-total"><td></td><td className="pd-n">{m.total.label}</td>
<td className="pd-cur">USD</td><td className="pd-n">{nBR(m.total.usd,2)}</td>
<td className="pd-cur">R$</td><td className="pd-n">{nBR(m.total.brl,2)}</td></tr>
</tbody>
