/* ============================================================
   ACESSO — identificação pela conta claude.ai + perfil no banco compartilhado
   Quando o sistema for para hospedagem própria, este é o ponto de troca para
   e-mail e senha (Supabase Auth); perfis e permissões continuam os mesmos.
   ============================================================ */
const ROLES={
  admin:{label:'Administrador',desc:'Tudo, inclusive cadastros e usuários'},
  financeiro:{label:'Financeiro',desc:'Cotações, aprovação, FDA, validação e emissão'},
  operacional:{label:'Operacional',desc:'Cotações e lançamento de despesas no FDA'},
  leitura:{label:'Leitura',desc:'Consulta de PDAs e FDAs, sem alterar'}
};
const PERMS={
  cadastros:['admin'],
  usuarios:['admin'],
  cotar:['admin','financeiro','operacional'],
  aprovar:['admin','financeiro'],
  fda_editar:['admin','financeiro','operacional'],
  fda_validar:['admin','financeiro'],
  fda_emitir:['admin','financeiro'],
  fda_finalizar:['admin','financeiro'],
  fda_reabrir:['admin']
};
const RoleCtx=React.createContext({role:'admin',mode:'local',me:{id:null,name:'',email:null},can:()=>true});
const useRole=()=>React.useContext(RoleCtx);
const canRole=(role,a)=>(PERMS[a]||[]).includes(role);

function AccessGate({children}){
/* o login, a liberação e a carga dos dados acontecem antes (plataforma/Raiz.jsx);
   aqui só se entrega o perfil ao sistema. As permissões vêm do banco. */
const s=window.__PDX__;
const value={role:s.role,mode:'conta',me:s.me,owner:s.role==='admin',editor:s.role==='admin',user:null,db:null,
  can:a=>s.perms.has(a),sair:s.sair};
return <RoleCtx.Provider value={value}>{children}</RoleCtx.Provider>;
}

/* ---------- Usuários e perfis (Cadastros › Organização) ---------- */
function UsersModule(){
const R=useRole();
const [rows,setRows]=useState(null), [reqs,setReqs]=useState([]);
const [novo,setNovo]=useState({name:'',email:'',role:'operacional'});
const [busy,setBusy]=useState(false);
const meId=window.__PDX__.me.id;
const erro=e=>{
  const m=(e&&(e.message||e.details))||String(e);
  toast(/row-level security/i.test(m)?'Seu perfil não tem permissão para esta alteração':m,'bad');
};
const carregar=async()=>{
  const [u,r]=await Promise.all([
    supabase.from('app_user').select('id,name,email,role,active,auth_id,created_at').order('name'),
    supabase.from('access_request').select('id,external_id,name,email,requested_at,status').eq('status','pending').order('requested_at')]);
  if(u.error)return erro(u.error);
  setRows(u.data); setReqs(r.data||[]);
};
useEffect(()=>{ carregar(); },[]);
const salvar=async(id,patch,msg)=>{
  setBusy(true);
  const {error}=await supabase.from('app_user').update(patch).eq('id',id);
  setBusy(false);
  if(error)return erro(error);
  toast(msg,'ok'); carregar();
};
const aprovar=async(rq,role)=>{
  setBusy(true);
  const nome=(rq.name||'').trim()||(rq.email||'').split('@')[0];
  const a=await supabase.from('app_user').insert({name:nome,email:rq.email,role,auth_id:rq.external_id});
  if(a.error){ setBusy(false); return erro(a.error); }
  await supabase.from('access_request').update({status:'approved',granted_role:role,decided_by:meId,decided_at:new Date().toISOString()}).eq('id',rq.id);
  setBusy(false); toast(`Acesso liberado para ${nome} — ${ROLES[role].label}`,'ok'); carregar();
};
const recusar=async rq=>{
  const {error}=await supabase.from('access_request').update({status:'rejected',decided_by:meId,decided_at:new Date().toISOString()}).eq('id',rq.id);
  if(error)return erro(error);
  toast('Solicitação recusada'); carregar();
};
const cadastrar=async()=>{
  const email=novo.email.trim().toLowerCase(), name=novo.name.trim();
  if(!name||!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))return toast('Informe nome e e-mail válidos','bad');
  setBusy(true);
  const {error}=await supabase.from('app_user').insert({name,email,role:novo.role});
  setBusy(false);
  if(error)return erro(/duplicate|unique/i.test(error.message)?{message:'Já existe um usuário com este e-mail'}:error);
  setNovo({name:'',email:'',role:'operacional'});
  toast('Usuário cadastrado. Agora envie o convite pelo Supabase.','ok'); carregar();
};
if(!R.can('usuarios'))return(
<div className="card"><div className="card-head"><div><h2>Usuários</h2></div></div>
<div className="note note-warn">Seu perfil não gerencia usuários.</div></div>);
return(
<div className="card">
<div className="card-head"><div><h2>Usuários e perfis</h2>
<div className="sub">Quem usa o sistema e o que cada um pode fazer</div></div></div>
<div className="tscroll" style={{marginBottom:18}}><table style={{minWidth:560}}>
<thead><tr><th>Perfil</th><th>O que pode fazer</th></tr></thead>
<tbody>{Object.entries(ROLES).map(([k,r])=><tr key={k}><td><span className="chip chip-info">{r.label}</span></td><td style={{fontSize:'.84rem'}}>{r.desc}</td></tr>)}</tbody></table></div>

{reqs.length>0&&<div className="panel">
<div className="panel-head"><h3>Solicitações de acesso · {reqs.length}</h3></div>
{reqs.map(r=>(
<div key={r.id} className="user-row">
<div><strong>{r.name||r.email}</strong><span>{r.email} · entrou em {new Date(r.requested_at).toLocaleDateString('pt-BR')}</span></div>
<div className="actions">
{['operacional','financeiro','leitura','admin'].map(k=>(
<button key={k} className="btn btn-line btn-sm" disabled={busy} onClick={()=>aprovar(r,k)}>Liberar como {ROLES[k].label}</button>))}
<button className="btn btn-bad btn-sm" disabled={busy} onClick={()=>recusar(r)}>Recusar</button></div>
</div>))}
</div>}

<div className="panel">
<div className="panel-head"><h3>Usuários · {rows?rows.length:'…'}</h3></div>
{(rows||[]).map(u=>{
  const eu=u.id===meId;
  return(
  <div key={u.id} className="user-row">
  <div><strong>{u.name}{eu?' (você)':''}</strong>
  <span>{u.email||'sem e-mail'} · {u.auth_id?'login ativo':'convite pendente'}{u.active?'':' · desativado'}</span></div>
  <div className="actions">
  <select value={u.role} disabled={busy||eu} onChange={e=>salvar(u.id,{role:e.target.value},`Perfil de ${u.name} alterado para ${ROLES[e.target.value].label}`)}>
  {Object.entries(ROLES).map(([k,r])=><option key={k} value={k}>{r.label}</option>)}</select>
  <button className={'btn btn-sm '+(u.active?'btn-bad':'btn-line')} disabled={busy||eu}
    onClick={()=>salvar(u.id,{active:!u.active},u.active?`${u.name} desativado`:`${u.name} reativado`)}>{u.active?'Desativar':'Reativar'}</button>
  </div></div>);})}
{eu_aviso()}
</div>

<div className="panel">
<div className="panel-head"><h3>Cadastrar usuário</h3></div>
<div className="grid-s">
<div className="field"><label>Nome</label><input value={novo.name} onChange={e=>setNovo({...novo,name:e.target.value})}/></div>
<div className="field"><label>E-mail corporativo</label><input type="email" value={novo.email} onChange={e=>setNovo({...novo,email:e.target.value})}/></div>
<div className="field"><label>Perfil</label><select value={novo.role} onChange={e=>setNovo({...novo,role:e.target.value})}>
{Object.entries(ROLES).map(([k,r])=><option key={k} value={k}>{r.label}</option>)}</select></div>
</div>
<button className="btn btn-primary btn-sm" disabled={busy} onClick={cadastrar} style={{marginTop:10}}>Cadastrar</button>
<div className="note" style={{marginTop:12}}>Depois de cadastrar, envie o convite no Supabase: <strong>Authentication › Users › Add user › Send invitation</strong>, com o mesmo e-mail. Quando a pessoa aceitar, o acesso é ligado automaticamente. Quem entrar sem cadastro aparece em Solicitações de acesso.</div>
</div>
</div>);
function eu_aviso(){ return <p style={{fontSize:'.8rem',color:'var(--fg-muted)',margin:'10px 0 0'}}>Ninguém altera o próprio perfil; o sistema exige sempre ao menos um administrador ativo.</p>; }
}

/* ============================================================
   APP
   ============================================================ */
function App(){
const R=useRole();
/* duas áreas: operação (dia a dia) e cadastros (base) */
const [area,setArea]=useState('op');
const [tab,setTab]=useState('quote');
const [cadTab,setCadTab]=useState('overview');
const [portSel,setPortSel]=useState(null);   /* {id, sub} — porto aberto no cadastro */
const [ports,setPorts]=useState(()=>migratePorts(store.get('ports',SEED_PORTS)));
const [terminals,setTerminals]=useState(()=>migrateTerminals(store.get('terminals',SEED_TERMINALS)));
const [shipowners,setShipowners]=useState(()=>migrateOwners(store.get('shipowners',SEED_SHIPOWNERS)));
const [companies,setCompanies]=useState(()=>migrateCompanies(store.get('companies',null),store.get('company',null)));
const [vessels,setVessels]=useState(()=>store.get('vessels',SEED_VESSELS));
/* Fornecedores saíram de dentro do porto e viraram cadastro próprio.
   Bases antigas são migradas uma vez, preservando os ids. */
const [suppliers,setSuppliers]=useState(()=>{
  const saved=store.get('suppliers',null);
  if(saved)return migrateSuppliers(saved);
  const legado=[];
  (store.get('ports',SEED_PORTS)||[]).forEach(p=>{
    (p.suppliers||[]).forEach(sp=>legado.push({...sp,portIds:[p.id]}));
  });
  return migrateSuppliers(legado.length?legado:SEED_SUPPLIERS);
});
const [quotations,setQuotations]=useState(()=>store.get('quotations',[]));
const [theme,setTheme]=useState(()=>store.get('theme',null));
const [toasts,setToasts]=useState([]);
const [req,setReq]=useState(null);
const resolver=useRef(null);

useEffect(()=>store.set('ports',ports),[ports]);
useEffect(()=>store.set('terminals',terminals),[terminals]);
useEffect(()=>store.set('shipowners',shipowners),[shipowners]);
useEffect(()=>store.set('vessels',vessels),[vessels]);
useEffect(()=>store.set('suppliers',suppliers),[suppliers]);
useEffect(()=>{ store.set('companies',companies); COMPANIES_REF=companies; },[companies]);
COMPANIES_REF=companies;
useEffect(()=>store.set('quotations',quotations),[quotations]);

useEffect(()=>{
  if(theme)document.documentElement.setAttribute('data-theme',theme);
  else document.documentElement.removeAttribute('data-theme');
  store.set('theme',theme);
},[theme]);

useEffect(()=>{
  UI.toast=(msg,kind)=>{
    const id=uid();
    setToasts(t=>[...t,{id,msg,kind}]);
    setTimeout(()=>setToasts(t=>t.filter(x=>x.id!==id)),3200);
  };
  UI.ask=(opts,resolve)=>{ resolver.current=resolve; setReq(opts); };
  return()=>{ UI.toast=null; UI.ask=null; };
},[]);

const answer=ok=>{ setReq(null); if(resolver.current){resolver.current(ok);resolver.current=null;} };

const [editQuote,setEditQuote]=useState(null);
const saveQuote=r=>{
  if(editQuote){
    /* substitui o rascunho: mesmo id e data de criação; comentários ajustados por terminal são mantidos */
    const old=quotations.find(x=>x.id===editQuote.id)||editQuote;
    const tr={...r.terminalResults};
    Object.keys(tr).forEach(k=>{
      const prev=(old.terminalResults||{})[k];
      if(prev&&prev.pdaComments&&!tr[k].pdaComments)tr[k]={...tr[k],pdaComments:prev.pdaComments};
    });
    const q={...old,...r,terminalResults:tr,id:old.id,date:old.date,status:'draft',updatedAt:new Date().toISOString()};
    setQuotations(quotations.map(x=>x.id===q.id?q:x));
    setEditQuote(null);
    toast(`Cotação #${q.id.slice(-6)} atualizada`,'ok');
    setTab('history');
    return;
  }
  const q={id:uid(),date:new Date().toISOString(),status:'draft',...r};
  setQuotations([q,...quotations]);
  toast(`Cotação #${q.id.slice(-6)} salva como rascunho`,'ok');
  setTab('history');
};
const editFromHistory=q=>{
  if(q.status==='approved')return toast('Cotação aprovada não pode ser editada — reabra como rascunho antes','bad');
  setEditQuote(q); setArea('op'); setTab('quote');
};

/* Conversão PDA → FDA: o pedido viaja ao módulo FDA, que tem acesso ao banco */
const [pendingFda,setPendingFda]=useState(null);
const openFdaFromQuote=(q,terminalName)=>{ setPendingFda({quote:q,terminalName}); setArea('op'); setTab('fda'); };
const fdaCreated=(quoteId,fdaId)=>{
  setPendingFda(null);
  setQuotations(qs=>qs.map(x=>x.id===quoteId?{...x,fdaId}:x));
};

const OP_TABS=[...(R.can('cotar')?[['quote',editQuote?'Editando cotação':'Nova cotação',null]]:[]),
  ['history','PDAs',quotations.length],['fda','FDAs',null]];
useEffect(()=>{ if(!R.can('cotar')&&tab==='quote')setTab('history'); if(!R.can('cadastros')&&area==='cad')setArea('op'); },[R.role]);
const counts={company:companies.length,owners:shipowners.length,vessels:vessels.length,ports:ports.length,
  terminals:terminals.length,suppliers:suppliers.length,
  contracts:shipowners.reduce((a,s2)=>a+(s2.terminalContracts||[]).length,0)};
const pend=pendencias({companies,shipowners,vessels,ports,terminals,suppliers});
const pendGraves=pend.filter(p=>p.sev==='bad').length;
const goCad=t=>{ setArea('cad'); setCadTab(t); };
/* navegação vinda da visão geral: aba simples ou porto + subaba */
const goPend=p=>{ setCadTab(p.tab); if(p.tab==='ports')setPortSel(p.port&&ports.some(x=>x.id===p.port)?{id:p.port,sub:p.sub||'tarifas'}:null); };

const isDark=theme==='dark'||(!theme&&window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches);

return(
<CompaniesCtx.Provider value={companies}><OwnersCtx.Provider value={shipowners}>
<div className="app">
<header className="masthead">
<img className="brand" src={'data:image/png;base64,'+LOGO_B64} alt="Seatrade"/>
<div>
<h1>PDA Express</h1>
<p>Cotação de custos portuários e prestação de contas</p>
</div>
<div className="who">
<div><strong>{R.me.name||'Usuário'}</strong><span>{ROLES[R.role].label}{R.mode==='local'?' · modo local':''}</span></div>
<button className="btn btn-line btn-sm" onClick={R.sair}>Sair</button></div>
<button className="theme-btn" style={{marginLeft:0}} onClick={()=>setTheme(isDark?'light':'dark')}
  aria-label={isDark?'Mudar para tema claro':'Mudar para tema escuro'}>{isDark?'☀':'☾'}</button>
</header>

{R.can('cadastros')&&<div className="areas">
<button className={area==='op'?'active':''} onClick={()=>setArea('op')}>
<span className="a-tag">Operação</span><span className="a-name">Cotações (PDA) e prestações de contas (FDA)</span></button>
<button className={area==='cad'?'active':''} onClick={()=>setArea('cad')}>
<span className="a-tag">Cadastros
{pend.length>0&&<span className={'a-badge '+(pendGraves?'bad':'warn')}>{pend.length}</span>}</span>
<span className="a-name">Empresas, clientes, tarifas e prestadores</span></button>
</div>}

{area==='op'&&<>
<nav className="nav">
{OP_TABS.map(([k,l,n])=>(
<button key={k} className={tab===k?'active':''} onClick={()=>setTab(k)}>
{l}{n!==null&&n>0&&<span className="count">{n}</span>}</button>))}
</nav>
{pendGraves>0&&tab==='quote'&&<div className="note note-bad" style={{display:'flex',gap:12,alignItems:'center',flexWrap:'wrap'}}>
<span style={{flex:1,minWidth:220}}>Há {pendGraves} pendência(s) crítica(s) nos cadastros que podem afetar esta cotação.</span>
<button className="btn btn-line btn-sm" onClick={()=>goCad('overview')}>Ver pendências</button></div>}
{tab==='quote'&&<QuoteModule key={editQuote?'edit-'+editQuote.id:'novo'} editing={editQuote}
  onCancelEdit={()=>{setEditQuote(null);setTab('history');}}
  ports={ports} terminals={terminals} shipowners={shipowners}
  vessels={vessels} suppliers={suppliers} onSave={saveQuote}/>}
{tab==='history'&&<HistoryModule quotations={quotations} setQuotations={setQuotations} onOpenFda={openFdaFromQuote} onEdit={editFromHistory}/>}
{tab==='fda'&&<FdaModule pending={pendingFda} onCreated={fdaCreated} onCancelPending={()=>setPendingFda(null)}
  companies={companies} shipowners={shipowners}/>}
</>}

{area==='cad'&&R.can('cadastros')&&<div className="cad">
<aside className="cad-menu" aria-label="Cadastros">
{CAD_MENU.map((g,gi)=>(
<div key={gi} className="cad-group">
{g.grupo&&<div className="cad-gt">{g.grupo}</div>}
{g.itens.map(([k,l])=>{
  const nP=pend.filter(p=>p.tab===k&&!p.port).length;
  const n=k==='overview'?null:counts[k];
  const act=cadTab===k&&!(k==='ports'&&portSel);
  return(
  <button key={k} className={act?'active':''} onClick={()=>{setCadTab(k); if(k==='ports')setPortSel(null);}}>
  <span>{l}</span>
  {k==='overview'&&pend.length>0&&<span className={'count '+(pendGraves?'bad':'warn')}>{pend.length}</span>}
  {k!=='overview'&&<span className="count">{n}</span>}
  {k!=='overview'&&nP>0&&<i className={'dot '+(pend.some(p=>p.tab===k&&!p.port&&p.sev==='bad')?'bad':'warn')} title={nP+' pendência(s)'}/>}
  </button>);})}
{g.portos&&ports.map(p=>{
  const pp=pend.filter(x=>x.port===p.id);
  const on=cadTab==='ports'&&portSel&&portSel.id===p.id;
  return(
  <div key={p.id}>
  <button className={'cad-sub'+(on?' active':'')} onClick={()=>{setCadTab('ports');setPortSel({id:p.id,sub:'tarifas'});}}>
  <span>{p.city}</span>
  {pp.length>0&&<i className={'dot '+(pp.some(x=>x.sev==='bad')?'bad':'warn')} title={pp.length+' pendência(s)'}/>}
  </button>
  {on&&[['tarifas','Tarifas da cidade'],['terminais','Terminais'],['fornecedores','Fornecedores']].map(([sk,sl])=>{
    const cnt=sk==='terminais'?terminals.filter(t=>t.portId===p.id).length
      :sk==='fornecedores'?suppliers.filter(x=>(x.portIds||[]).includes(p.id)).length:null;
    return(
    <button key={sk} className={'cad-sub2'+(portSel.sub===sk?' active':'')} onClick={()=>setPortSel({id:p.id,sub:sk})}>
    <span>{sl}</span>{cnt!==null&&<span className="count">{cnt}</span>}</button>);})}
  </div>);})}
</div>))}
</aside>
<div className="cad-body">
{cadTab==='overview'&&<CadOverview counts={counts} pend={pend} go={goPend}/>}
{cadTab==='company'&&<CompaniesModule companies={companies} setCompanies={setCompanies} shipowners={shipowners}/>}
{cadTab==='users'&&<UsersModule/>}
{cadTab==='owners'&&<OwnersModule shipowners={shipowners} setShipowners={setShipowners} vessels={vessels} terminals={terminals} ports={ports} companies={companies}/>}
{cadTab==='vessels'&&<VesselsModule vessels={vessels} setVessels={setVessels} shipowners={shipowners}/>}
{cadTab==='contracts'&&<ContractsModule shipowners={shipowners} terminals={terminals} ports={ports}/>}
{cadTab==='ports'&&<PortsModule ports={ports} setPorts={setPorts} terminals={terminals} setTerminals={setTerminals}
  suppliers={suppliers} setSuppliers={setSuppliers} sel={portSel} setSel={setPortSel}/>}
</div>
</div>}

<ConfirmDialog req={req} onAnswer={answer}/>
<Toasts items={toasts}/>
</div>
</OwnersCtx.Provider></CompaniesCtx.Provider>);
}

export { App, AccessGate, COA, calculate, LOGO_B64, ROLES };
